"""Manuscrito editable del manual. Los fragmentos se extraen del código real."""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parent.parent
BLOCKS = []
def add(kind, **kw): BLOCKS.append(dict(kind=kind, **kw))
def chapter(title, subtitle=''): add('chapter', title=title, subtitle=subtitle)
def h(title): add('heading', text=title)
def p(text): add('paragraph', text=text)
def note(title, text): add('callout', title=title, text=text)
def steps(*items): add('list', items=list(items), ordered=True)
def bullets(*items): add('list', items=list(items), ordered=False)
def table(headers, rows, widths=None): add('table', headers=headers, rows=rows, widths=widths)
def code(text, language='typescript', label='Ejemplo didáctico'): add('code', text=text.strip('\n'), language=language, label=label)
def source(path, first=1, last=None):
    lines=(ROOT/path).read_text().splitlines(); last=last or len(lines)
    add('code', text='\n'.join(lines[first-1:last]), language=Path(path).suffix.lstrip('.'), label=f'{path} · líneas {first}–{last}', start=first)
def image(path, caption, height=260): add('image', path=path, caption=caption, height=height)
def diagram(title, boxes): add('diagram', title=title, boxes=boxes)
def fileintro(path, purpose, before, after):
    h('Qué vas a crear y dónde encaja')
    table(['Archivo','Responsabilidad'],[[path,purpose],['Antes de escribirlo',before],['Al terminar',after]], [0.29,0.71])
    p('Crea este archivo con el nombre y la extensión indicados, guarda el texto en UTF-8 y conserva la ruta relativa. El código íntegro aparece en el anexo A; los números de línea corresponden a esa copia exacta. Los ejemplos breves del capítulo sirven para comprender una idea y no sustituyen por sí solos el archivo completo.')

chapter('Cómo utilizar este libro', 'Una ruta para aprender, construir y consultar sin depender del chat.')
p('Este manual está escrito para que puedas reconstruir por tu cuenta el prototipo SG-CICT que ya tienes funcionando. No presupone que conozcas un framework web. Parte de archivos, funciones, objetos, formularios y consultas SQL, y explica cómo esas piezas se conectan hasta producir una aplicación utilizable.')
p('El punto de partida es tu carpeta prototipo. La guía documenta su versión actual, no una aplicación distinta. Incluye el código de todos los archivos de texto de la aplicación y su documentación original, más las capturas de referencia. La base SQLite y las sesiones de tu equipo son datos de ejecución: no se copian al manual ni al paquete de fuentes.')
h('Tres formas de leerlo')
table(['Objetivo','Cómo recorrer el manual'],[
 ['Construir desde cero','Sigue los capítulos en orden. Escribe los archivos en una carpeta nueva llamada sg-cict-aprendizaje y comprueba cada etapa.'],
 ['Entender una función','Busca el capítulo de su archivo y después consulta el código numerado del anexo A.'],
 ['Cambiar una funcionalidad','Revisa primero el recorrido completo de la operación y las pruebas que fijan su comportamiento.']])
note('Construye en otra carpeta', 'Tu prototipo actual puede seguir abierto mientras estudias. Trabaja en sg-cict-aprendizaje, usa una base propia y, si hay otra instancia funcionando, un puerto diferente. Así puedes comparar resultados sin alterar tus reservas de demostración.')
h('Cómo interpretar el código')
p('Los recuadros «Ejemplo didáctico» explican conceptos de forma reducida. Los recuadros con ruta y líneas proceden de tus archivos reales. El anexo A contiene la copia completa, sin omisiones: las líneas largas se parten visualmente, pero conservan su número original. No escribas los números ni las marcas de continuación dentro del archivo.')
p('El HTML que acompaña al PDF mantiene los bloques seleccionables sin números añadidos al texto. El ZIP de fuentes conserva los archivos originales y permite comprobar lo que has escrito. Utiliza esos recursos para comparar; intenta explicar cada bloque antes de copiarlo.')
h('Qué aprenderás')
bullets('Distinguir lo que ejecuta el navegador de lo que ejecuta Node.', 'Definir datos con TypeScript y validar entradas que llegan por HTTP.', 'Guardar cambios con SQLite, consultas preparadas y transacciones.', 'Implementar reservas, disponibilidad técnica, cancelaciones e incidencias.', 'Construir pantallas con HTML, CSS y eventos, sin un framework.', 'Verificar reglas con pruebas que controlan el reloj y la base de datos.')
h('Lo que representa esta aplicación')
p('Es un prototipo educativo con cuentas, empresas, instrumentos y contratos ficticios. El acceso UCO se comprueba contra cuentas locales, sin conexión a Moodle. Los avisos se guardan en una bandeja y representan correos; no se envían mensajes reales. Las tarifas, el despliegue institucional y la comprobación normativa no están resueltos por este ejemplo.')
image('docs/capturas/02-panel.png','Resultado de referencia: panel principal de administración.', 280)

chapter('Preparar el entorno y la carpeta', 'Antes del primer archivo: terminal, versión de Node y comprobaciones.')
h('1. Comprueba Node')
code('node --version\nnode -e "console.log(typeof require(\'node:sqlite\').DatabaseSync)"', 'bash', 'Comandos de comprobación')
p('La primera orden debe mostrar una versión 24 o superior; el prototipo original se verificó con Node 26.13.1. La segunda debe mostrar function. Node es el programa que ejecutará el servidor TypeScript, atenderá peticiones y abrirá SQLite. El navegador será otro programa distinto que visitará la dirección local.')
p('Si Node no está instalado o es demasiado antiguo, utiliza el instalador o gestor de versiones de tu sistema. La aplicación no necesita npm para arrancar. No mezcles la ausencia de npm con un fallo de Node: todos los comandos principales de esta guía se ejecutan directamente con node.')
h('2. Crea un espacio independiente')
code('mkdir -p sg-cict-aprendizaje/src sg-cict-aprendizaje/public sg-cict-aprendizaje/tests\nmkdir -p sg-cict-aprendizaje/scripts sg-cict-aprendizaje/docs/capturas sg-cict-aprendizaje/data\ncd sg-cict-aprendizaje', 'bash', 'Linux y macOS: preparar directorios')
code('New-Item -ItemType Directory -Force sg-cict-aprendizaje\nSet-Location sg-cict-aprendizaje\nNew-Item -ItemType Directory -Force src,public,tests,scripts,docs,docs/capturas,data', 'powershell', 'PowerShell: preparar directorios')
p('Puedes crear archivos desde tu editor. No es necesario crear archivos vacíos con un comando antes de escribirlos: guardar un documento nuevo con la ruta correcta produce el mismo resultado. Mantén activada la visualización de extensiones para evitar nombres como server.ts.txt.')
h('3. Distingue ruta actual y ruta del archivo')
p('La orden node src/server.ts se interpreta desde la carpeta actual de la terminal. Si estás en proyecto-git, primero debes entrar en prototipo. Si estás dentro de prototipo, no vuelvas a anteponer prototipo/. Un error Cannot find module suele indicar esa confusión o un nombre de archivo incorrecto.')
code('pwd\nls\nnode src/server.ts', 'bash', 'Ejecutar desde la raíz de tu aplicación')
h('4. Aprende a detener y a cambiar el puerto')
p('El servidor ocupa la terminal porque sigue esperando peticiones. Detenerlo con Ctrl+C es normal. No necesitas arrancar otra copia cada vez que recargas el navegador. Una nueva ejecución en el mismo puerto mientras sigue abierta la anterior produce EADDRINUSE.')
code('PORT=4300 node src/server.ts', 'bash', 'Otra instancia en Linux/macOS')
code("$env:PORT = '4300'\nnode src/server.ts", 'powershell', 'Otra instancia en PowerShell')
note('Tu error EADDRINUSE, explicado', 'Solo un proceso puede escuchar en la misma dirección y puerto. Si ya hay una copia en localhost:4173, utiliza esa ventana del navegador o detén esa copia antes de volver a ejecutar Node. No borres SQLite para resolver un puerto ocupado.')
h('5. Trabaja con cambios pequeños')
steps('Escribe un archivo y comprueba que las importaciones apuntan a archivos existentes.', 'Ejecuta una comprobación apropiada para esa etapa.', 'Anota qué has añadido y el resultado que has observado.', 'Guarda una versión cuando una etapa funcione; evita reunir todos los cambios en un único commit final.')

chapter('Mapa de la aplicación y orden de construcción', 'Qué depende de qué y por qué no conviene empezar por la pantalla más grande.')
diagram('Una petición completa', ['Navegador\nHTML + CSS + JS','Servidor HTTP\nserver.ts','Reglas y acceso\nsystem.ts / auth.ts','Persistencia\nSQLite'])
p('El navegador no abre el archivo SQLite ni decide si una prioridad UCO es válida. Recoge datos y pide una operación. El servidor identifica al usuario, aplica reglas y devuelve un resultado. Esta separación permite comprobar una regla sin abrir un navegador y evita confiar en valores que cualquiera puede modificar desde las herramientas del cliente.')
table(['Etapa','Archivos','Resultado de la etapa'],[
 ['1 · Contratos','package.json, .gitignore, src/model.ts','Datos y nombres de estados definidos.'],
 ['2 · Datos y tiempo','src/time.ts, src/schema.sql, src/database.ts','Fechas válidas y una base que se puede abrir.'],
 ['3 · Acceso y semilla','src/auth.ts, src/seed.ts','Cuentas ficticias y sesiones utilizables.'],
 ['4 · Reglas','src/system.ts','Operaciones completas probables desde TypeScript.'],
 ['5 · Entrada web','src/server.ts, public/index.html y archivos públicos','Servidor local y documento servido por HTTP.'],
 ['6 · Interfaz','public/ui.ts, public/views.ts, public/app.ts, public/styles.css','Recorridos completos desde formularios.'],
 ['7 · Verificación','tests/*.test.ts, scripts/check.ts','Reglas y persistencia verificables.'],
 ['8 · Referencia','scripts/reset.ts, scripts/browser-check.ts, README y docs','Demostración repetible y documentación.']])
p('El servidor prepara tres módulos del navegador al construirse: app.ts, ui.ts y views.ts. Por eso, al probar server.ts por primera vez deben existir esos tres archivos, aunque al principio contengan solo export {}. Es un andamio temporal. Sustitúyelos por sus versiones completas al construir la interfaz.')
code('export {};', 'typescript', 'Contenido temporal de cada módulo público todavía no escrito')
note('Una etapa parcial no es la aplicación final', 'Si app.ts contiene solo export {}, la página no iniciará sesión ni dibujará las pantallas. Eso es esperable durante el andamio. No presentes esa etapa como un error de la versión completa.')
h('Los archivos que no escribes a mano')
table(['Archivo o grupo','Cómo aparece'],[
 ['data/prototipo.sqlite','Lo crea openDatabase al arrancar por primera vez.'],['data/prototipo.sqlite-wal y -shm','Los puede crear SQLite al utilizar WAL. Son archivos auxiliares.'],['data/backups/*.sqlite','Los crea reset.ts antes de reiniciar una base existente.'],['docs/capturas/*.png','Los genera la revisión del navegador o una captura manual.'],['data/.gitkeep','Archivo vacío para conservar el directorio en Git.']])
p('No abras SQLite como si fuese código de texto ni copies una base con sesiones al paquete que vas a compartir. El esquema y la semilla son los que permiten reproducir la demostración.')

chapter('TypeScript y web: lo necesario para leer el código', 'Sintaxis que aparece realmente en este proyecto, con ejemplos pequeños.')
h('Variables, objetos y funciones')
code("const nombre: string = 'Balanza';\nlet disponible: boolean = true;\nfunction horas(inicio: number, fin: number): number {\n  return (fin - inicio) / 3_600_000;\n}")
p('const impide reasignar la variable; no convierte un objeto en inmutable. let permite reasignarla. El texto después de dos puntos describe un tipo para el desarrollo. La función recibe argumentos, calcula y devuelve un valor. En este proyecto los instantes son números de milisegundos, no objetos Date guardados dentro de SQLite.')
h('Interfaces, uniones y valores nulos')
code("type Estado = 'confirmada' | 'cancelada';\ninterface Ejemplo {\n  id: number;\n  estado: Estado;\n  tecnicoId: number | null;\n  nombreVisible?: string;\n}")
p('La unión limita los nombres que expresa el programa. null significa que el campo tiene explícitamente ausencia de valor. El signo ? indica que la propiedad puede no estar presente; es útil cuando el servidor omite datos por privacidad. Ninguna de estas anotaciones valida automáticamente el JSON recibido por HTTP.')
h('Importaciones de ejecución y de tipos')
code("import { DomainError } from './model.ts';\nimport type { User } from './model.ts';")
p('DomainError es una clase que se necesita al ejecutar el programa. User es una descripción que desaparece cuando se eliminan los tipos. En los módulos del navegador se importan ui.js y views.js porque el servidor entrega JavaScript, aunque los originales se llamen ui.ts y views.ts.')
h('El símbolo !, as y as unknown as')
p('Un ! al final, como document.querySelector(... )!, afirma al analizador que el resultado no es nulo. No crea el elemento ni lo comprueba. La expresión as cambia la interpretación de tipos; tampoco transforma ni valida los datos. as unknown as aparece para interpretar filas de SQLite como interfaces conocidas. Su seguridad depende de que la consulta y el esquema coincidan.')
h('Operadores que verás a menudo')
table(['Expresión','Significado práctico'],[['a?.b','Lee b solo si a no es null ni undefined.'],['a ?? otro','Usa otro cuando a es null o undefined.'],['a || otro','Usa otro ante cualquier valor falsy, incluido 0 o cadena vacía.'],['...objeto','Copia sus propiedades en otro objeto.'],['condicion ? x : y','Escoge una de dos expresiones.'],['value => value.id','Función flecha que recibe un valor y devuelve su id.']])
h('Colecciones: map, filter, find, every y some')
code("const confirmadas = reservas.filter(r => r.estado === 'confirmada');\nconst ids = confirmadas.map(r => r.id);\nconst primera = confirmadas.find(r => r.id === 7);\nconst hayAlguna = confirmadas.some(r => r.tecnicoId === 4);\nconst todasPropias = confirmadas.every(r => r.usuarioId === 2);")
p('map transforma, filter conserva coincidencias y find devuelve la primera o undefined. some responde si hay alguna coincidencia; every exige que todas cumplan la condición. every sobre una lista vacía devuelve true: en la asignación de técnicos esto permite considerar libre a quien no tiene citas incompatibles.')
h('Promesas y async/await')
p('Una petición fetch no produce su respuesta inmediatamente. async hace que una función devuelva una promesa; await espera ese resultado dentro de la función sin convertir la red en una operación síncrona. La base del prototipo sí utiliza DatabaseSync: sus llamadas ocupan el proceso mientras se ejecutan. No mezcles ambas ideas al escribir una transacción.')
h('HTML, DOM y CSS')
p('HTML describe la estructura; el DOM es la representación de ese documento que puede consultar JavaScript. CSS decide la presentación. Una clase como button primary se utiliza para estilo. Un atributo como data-action="book" identifica una interacción. Un id como purpose relaciona un label con su campo y permite encontrarlo dentro del diálogo.')
h('HTTP, JSON y estados')
p('GET consulta. POST solicita un cambio. JSON representa los datos que se intercambian. Una respuesta 200 indica consulta u operación correcta; 201, creación; 400, entrada inválida; 401, falta de acceso autenticado; 403, permiso insuficiente; 409, conflicto. Un error de negocio comprensible no debería transformarse en un fallo interno 500.')
note('Ejecutar TypeScript no es comprobar los tipos', 'Node elimina las anotaciones compatibles y ejecuta el resultado. check.ts verifica transformación y construcción, pero no realiza el análisis estático de tsc. Es una diferencia real del prototipo; no interpretes una ejecución correcta como una prueba de corrección de todos los tipos.')

chapter('Configuración: package.json y .gitignore', 'Los dos archivos pequeños que dan contexto al resto.')
fileintro('package.json','Identidad del proyecto, módulos ES, versión mínima y comandos abreviados.','Node instalado y directorios creados.','Node reconoce los .ts como módulos del proyecto y tienes los comandos documentados.')
source('package.json')
steps('Escribe un objeto JSON válido: claves entre comillas dobles, comas entre propiedades y sin comentarios.', 'Incluye type: module para que las importaciones y exportaciones se interpreten como módulos ES.', 'Declara engines para explicar la versión mínima. Ese campo orienta; no actualiza tu instalación de Node.', 'Define start, dev, test y check. Son atajos para quien tenga npm, no dependencias necesarias para arrancar.')
p('private: true evita publicar accidentalmente este paquete con los flujos habituales de npm. No hace privada una web ni aplica permisos a los datos. La versión 0.1.0 describe el paquete, mientras que los cambios de tablas necesitan su propio tratamiento de esquema.')
h('.gitignore: qué debe quedarse fuera')
source('.gitignore')
p('Las reglas excluyen las bases y sus auxiliares, las copias, node_modules y archivos de ejecución. El esquema schema.sql y la semilla seed.ts sí deben guardarse porque permiten reproducir los datos. Un archivo ya seguido por Git no deja de estarlo solo por añadirlo después a .gitignore.')
h('Comprobación')
code("node -e \"console.log(JSON.parse(require('node:fs').readFileSync('package.json','utf8')).type)\"", 'bash')
p('Debe mostrar module. Si aparece un error de JSON, revisa comas y comillas antes de buscar fallos en TypeScript.')

chapter('src/model.ts: el vocabulario de los datos', 'Escribe primero los contratos que compartirán los demás módulos.')
fileintro('src/model.ts','Describir datos, entradas, vistas y errores esperados.','Los estados y perfiles del sistema están acordados.','Otros archivos pueden importar tipos sin duplicar estructuras.')
h('Cómo escribirlo, en orden')
steps('Define Role con los seis perfiles exactos: admin, uco, externo, tecnico, contable y consulta.', 'Define BookingStatus con confirmada, cancelada, desplazada, en_uso y finalizada.', 'Escribe User e Instrument: representan las cuentas y el catálogo.', 'Escribe Booking: guarda intervalos, relaciones, estado, tipo y uso real.', 'Añade BookingView, que incorpora nombres de presentación y la marca own.', 'Escribe Incident, Notification, ReportRow y Snapshot.', 'Termina con BookingInput y la clase DomainError.')
table(['Tipo','Qué significa y qué debes vigilar'],[
 ['User','active es 0/1 porque procede de SQLite. El rol controla operaciones y las fechas delimitan el contrato. No contiene passwordHash.'],
 ['Instrument','needsTechnician es 0/1. El estado persistente solo es disponible o averiado; mantenimiento se representa como reserva.'],
 ['Booking','userId e instrumentId son referencias. technicianId, actualStart y actualEnd pueden ser null.'],
 ['BookingView','Añade datos calculados al consultar. userName y company son opcionales por privacidad.'],
 ['Incident','La resolución y resolvedAt son null mientras el parte sigue abierto. El nombre del equipo procede de una unión SQL.'],
 ['Notification','readAt diferencia leído y pendiente. El destinatario está identificado por userId.'],
 ['ReportRow','Separa uso real y cancelación tardía. totalHours es una agregación, no un importe.'],
 ['Snapshot','Agrupa el estado que la interfaz necesita después de aplicar permisos.'],
 ['BookingInput','Recibe fecha local como texto y un identificador; no acepta decidir el propietario.']])
source('src/model.ts',14,25)
p('extends Booking evita repetir todos los campos de la reserva en BookingView. La palabra own no viene de una casilla que marque el navegador: el servidor la calcula comparando el propietario con la persona autenticada.')
h('DomainError: un error que el servidor sabe explicar')
source('src/model.ts',44,48)
p('La clase hereda de Error y añade status. El valor por defecto es 400. Al crear DomainError con 409 expresas un conflicto conocido; al crear un Error inesperado de programación, el servidor lo trata como fallo interno. El nombre de la clase permite distinguir ambos con instanceof.')
h('Comprueba que lo entiendes')
bullets('Explica por qué actualEnd es null antes de terminar la sesión.', 'Explica por qué passwordHash no debe formar parte de User público.', 'Distingue la entrada BookingInput de la fila Booking y de la vista BookingView.')
note('No inventes un enum para copiar este archivo', 'El prototipo utiliza uniones de literales, compatibles con la eliminación de tipos. Un enum tradicional puede necesitar transformación de código adicional; no lo introduzcas suponiendo que funciona igual en este arranque.')

chapter('src/time.ts: fechas, zonas e intervalos', 'La misma hora escrita puede representar instantes distintos en invierno y verano.')
fileintro('src/time.ts','Convertir fechas de Madrid, comparar intervalos y validar franjas.','DomainError ya existe.','Una reserva puede validar su fecha sin depender del navegador.')
h('Constantes y formato local')
p('HOUR equivale a 3 600 000 milisegundos y DAY a 24 horas de duración. TIMEZONE fija Europe/Madrid. El formato sv-SE se usa para obtener números en orden año-mes-día; la zona horaria se fija explícitamente y no depende del idioma del usuario.')
source('src/time.ts',1,14)
p('localDateTime convierte un instante numérico a texto local AAAA-MM-DDTHH:mm. El reemplazo cambia el espacio por T y slice elimina los segundos. Este texto sirve para formularios y comparaciones de hora cuando se ha verificado antes su estructura.')
h('parseLocalDateTime paso a paso')
steps('Rechaza entradas que no sean texto con la forma exacta esperada.', 'Extrae año, mes, día, hora y minuto y conviértelos en números.', 'Aplica límites sencillos al año, mes, hora y minuto.', 'Construye una referencia con Date.UTC; todavía no es la respuesta local definitiva.', 'Formatea el candidato en Madrid, calcula la diferencia respecto al objetivo y corrige el instante.', 'Repite la corrección hasta tres veces.', 'Comprueba que el resultado vuelve exactamente al texto original; así se rechazan fechas normalizadas como un 30 de febrero.')
p('La corrección es necesaria porque 10:00 en Madrid corresponde a 09:00 UTC en invierno y a 08:00 UTC en verano. No restes siempre una hora: esa simplificación falla varios meses del año. El formulario de reservas solo permite 08–20, lejos de la franja nocturna donde cambia el reloj; el prototipo no pretende ser una biblioteca general para desambiguar cualquier hora nocturna de cambio estacional.')
h('Intervalos semiabiertos')
source('src/time.ts',35,38)
code('overlaps(8, 10, 10, 12) // false\noverlaps(8, 11, 10, 12) // true')
p('Para solapar, el inicio de cada intervalo tiene que quedar antes del final del otro. Usar < permite que una reserva termine a las 11:00 y otra empiece a las 11:00. La misma desigualdad aparece en las consultas SQL de disponibilidad; mantenerlas equivalentes evita resultados contradictorios.')
h('validateSlot y monthRange')
p('validateSlot convierte ambas fechas, rechaza un inicio anterior a now, un fin no posterior y una franja fuera de 08–20 o que cruza de día. Fíjate en el detalle del código: start < now permite igualdad exacta con el reloj, aunque el mensaje diga futuro. En una interfaz que envía minutos y un reloj con segundos, esa igualdad es poco habitual. Si necesitas futuro estrictamente posterior, cambia la comparación y añade una prueba del límite.')
p('monthRange recibe AAAA-MM, valida mes y año y devuelve el primer instante del mes y el primer instante del siguiente. El límite de fin es exclusivo. En diciembre calcula enero del año posterior. No supone que todos los meses duren treinta días ni que un mes tenga siempre el mismo número de horas.')
h('Comprueba la conversión sin arrancar el servidor')
code("node --input-type=module -e \"import {parseLocalDateTime} from './src/time.ts'; console.log(new Date(parseLocalDateTime('2026-07-15T10:00')).toISOString())\"", 'bash')
p('El resultado para ese ejemplo de verano es 2026-07-15T08:00:00.000Z. Cambiar la fecha por invierno debe cambiar el desfase, no la hora de Madrid que has solicitado.')

chapter('src/schema.sql: diseñar la persistencia', 'Las tablas guardan hechos; sus restricciones evitan estados inválidos básicos.')
fileintro('src/schema.sql','Crear tablas, relaciones, restricciones e índices.','Conoces User, Instrument y Booking.','SQLite puede guardar el dominio con claves externas y estados definidos.')
h('Cómo escribir una tabla')
source('src/schema.sql',1,9)
p('INTEGER PRIMARY KEY es el identificador de una fila. NOT NULL exige un valor. UNIQUE impide repetir el correo y COLLATE NOCASE hace que su comparación ignore diferencias habituales entre mayúsculas y minúsculas. CHECK limita perfiles, valores 0/1 y el orden de las fechas del contrato.')
h('Las siete tablas, una a una')
table(['Tabla','Campos y decisión principal'],[
 ['users','Cuenta y contrato. passwordHash guarda sal y resultado de scrypt; nunca la contraseña en texto.'],
 ['instruments','Catálogo, sala, técnica y supervisión. No se crea una reserva de sala exclusiva.'],
 ['bookings','Referencias a usuario, instrumento y técnico; fechas previstas/reales, tipo, estado y cancelación.'],
 ['incidents','Parte vinculado al equipo y a quien lo abre. Puede permanecer sin resolución.'],
 ['notifications','Bandeja por destinatario con fecha de lectura. No es una tabla de correos enviados realmente.'],
 ['sessions','Token resumido, persona, CSRF y caducidad. El token original solo viaja en la cookie.'],
 ['activity','Eventos breves para el panel. No pretende ser una auditoría completa e inmutable.']])
h('Claves externas e índices')
p('REFERENCES users(id) exige que exista la cuenta referenciada cuando las claves externas están activas. La reserva conserva identificadores estables, no copias del nombre. Los índices combinan instrumento/tiempo y técnico/tiempo porque esas son las condiciones que se consultan al comprobar conflictos.')
p('El índice acelera la búsqueda, pero no hace por sí solo que dos intervalos no se solapen. Esa regla exige una consulta y una decisión dentro de una transacción. Tampoco un CHECK comprueba toda la máquina de estados: las operaciones de CictSystem deciden qué transición está permitida.')
h('Por qué varias columnas son INTEGER y no una fecha SQL')
p('Se guardan instantes en milisegundos para comparar duraciones sin mezclar formatos de texto. La interpretación local de un formulario ocurre antes, en time.ts. actualStart y actualEnd son null hasta que se registran; billableCancellation y active usan 0/1 para representar booleanos de forma explícita.')
h('Comprobación incremental')
code("node --input-type=module <<'JS'\nimport { DatabaseSync } from 'node:sqlite';\nimport { readFileSync } from 'node:fs';\nconst db = new DatabaseSync(':memory:');\ndb.exec(readFileSync('src/schema.sql', 'utf8'));\nconsole.log(db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all());\ndb.close();\nJS", 'bash', 'Linux/macOS: comprobar el esquema sin crear una base persistente')
p('Si prefieres evitar las comillas anidadas de la terminal, escribe ese pequeño programa como scripts/comprobar-esquema.ts. El resultado debe incluir las siete tablas. El archivo temporal de comprobación no forma parte del prototipo original.')
note('CREATE IF NOT EXISTS no es una migración', 'Editar una columna del schema.sql no modifica una tabla ya existente. En la demostración puedes crear otra base o reiniciar datos con copia. Para conservar datos reales se necesita una migración explícita; no borres la base como respuesta automática a cualquier cambio.')

chapter('src/database.ts: abrir y confirmar cambios', 'Un módulo pequeño que concentra la conexión y las transacciones.')
fileintro('src/database.ts','Abrir SQLite y ejecutar una operación atómica.','schema.sql existe; los imports de Node están disponibles.','Las reglas reciben una conexión y pueden confirmar o revertir cambios.')
source('src/database.ts')
h('openDatabase explicado')
p('El valor por defecto :memory: crea una base que vive solo durante esa conexión. Resulta útil para las pruebas. Una ruta real genera un archivo persistente. Se activan las claves externas y se fija busy_timeout para esperar un tiempo limitado cuando otro escritor ocupa la base.')
p('En un archivo persistente se activa WAL, un modo de registro que puede producir archivos -wal y -shm. Después se lee schema.sql utilizando una URL relativa al propio módulo. Esta forma evita depender de la carpeta desde la que se haya lanzado la terminal para localizar el esquema.')
h('transaction explicado')
steps('BEGIN IMMEDIATE inicia una transacción que solicita desde el comienzo el acceso de escritura.', 'Se ejecuta work, una función que devuelve el resultado de la operación.', 'Si todo termina correctamente, COMMIT confirma.', 'Si cualquier parte lanza una excepción, ROLLBACK revierte y se vuelve a lanzar el mismo error.')
p('La función genérica <T> significa que conserva el tipo del resultado de work. No fija que siempre devuelva un número. Una reserva puede devolver su id; una reparación puede no devolver contenido. Esta envoltura está diseñada para trabajo síncrono: no pases una función async que salga del bloque antes de completar sus escrituras.')
h('Ejemplo de uso')
code("const id = transaction(db, () => {\n  const result = db.prepare('INSERT INTO ... VALUES (?)').run(valor);\n  return Number(result.lastInsertRowid);\n});")
p('La sentencia INSERT de este recuadro está abreviada a propósito y no es ejecutable: sirve para ver la forma de uso. El INSERT real de reservas aparece en system.ts y en su anexo. No anides llamadas a esta envoltura porque BEGIN/COMMIT no se anidan directamente.')
h('Qué debes comprobar')
bullets('Una inserción válida queda guardada tras confirmar.', 'Una excepción en medio de dos escrituras no deja la primera confirmada.', 'Siempre cierras las conexiones de prueba al terminar.')

chapter('src/auth.ts: cuentas, contraseñas y sesiones', 'Autenticar identifica; autorizar decide qué puede hacer esa identidad.')
fileintro('src/auth.ts','Verificar credenciales, contrato y sesiones con caducidad.','User, DomainError, HOUR y una conexión SQLite.','Puedes iniciar, comprobar y cerrar una sesión sin abrir la interfaz.')
h('USER_COLUMNS evita devolver el resumen de contraseña')
p('La constante lista las columnas públicas de una cuenta. login necesita leer passwordHash para verificar, pero después vuelve a consultar solo las columnas públicas. No devuelvas directamente SELECT * FROM users al navegador: mezclarías datos operativos con el secreto derivado de la contraseña.')
h('hashPassword y verifyPassword')
source('src/auth.ts',1,16)
p('randomBytes crea una sal aleatoria de 16 bytes. Se convierte a hexadecimal para guardarla como texto. scryptSync deriva 64 bytes a partir de contraseña y sal. El resultado almacenado tiene forma sal:resumen. Dos personas con la misma contraseña no deberían obtener el mismo texto almacenado gracias a las sales distintas.')
p('Verificar separa ambos componentes, vuelve a derivar y compara con timingSafeEqual, después de comprobar longitud. Un resumen no se descifra para recuperar la contraseña. La sal no tiene que ocultarse; su función es evitar que todas las cuentas compartan el mismo cálculo base.')
h('assertAccess: quién puede entrar ahora')
p('Primero se rechaza una cuenta desactivada. Para uco y externo, también se exige que now esté dentro del contrato. Los perfiles internos del ejemplo no están sujetos a esa comprobación de contrato. Las operaciones posteriores vuelven a comprobar el acceso para aplicar cambios de vigencia durante una sesión.')
h('La clase Auth y la dependencia now')
p('El constructor recibe db y una función de reloj. En ejecución normal se usa Date.now. En una prueba se pasa una función que devuelve un instante fijo. Así puedes probar ocho horas de caducidad sin esperar ocho horas y un contrato vencido sin depender del día real de tu ordenador.')
p('digest es la ayuda que calcula SHA-256 del token para guardarlo y buscarlo sin persistir el valor original de la cookie.')
h('login, paso por paso')
steps('Normaliza el correo con trim y minúsculas y busca la fila con una consulta preparada.', 'Calcula también un scrypt ficticio si no existe la cuenta; evita responder de forma trivialmente más rápida solo por esa ausencia.', 'Si el resultado es incorrecto, lanza un 401 genérico de credenciales.', 'Comprueba cuenta activa y vigencia del contrato.', 'Obtiene la versión pública de User.', 'Genera un token aleatorio de 32 bytes y un CSRF de 24.', 'Elimina sesiones ya caducadas.', 'Guarda el SHA-256 del token, userId, csrf y fecha de caducidad a ocho horas.', 'Devuelve el token al nivel HTTP para la cookie y los datos públicos al cliente.')
p('La cookie identifica la sesión. El token CSRF es otro valor que la aplicación devuelve y exige en las escrituras. No son contraseñas adicionales que el usuario tenga que teclear. Sus controles se completan en server.ts: HttpOnly, SameSite, origen y comprobación de la cabecera.')
h('session y logout')
p('session resume el token recibido, busca una sesión aún vigente y carga de nuevo la cuenta. assertAccess vuelve a aplicarse. logout borra la fila que coincide con el resumen del token. Borrar solo una variable de JavaScript no cerraría una sesión que siga existiendo en el servidor.')
h('Comprobación después de crear la semilla')
code("const auth = new Auth(db, () => instanteDePrueba);\nconst session = auth.login('uco@demo.local', 'Demo2026!');\nconsole.log(session.user.role); // uco\nauth.logout(session.token);")
note('Límite del ejemplo', 'Se utiliza scryptSync para mantener el código fácil de seguir. Ese cálculo ocupa el proceso mientras trabaja. No conviertas este prototipo local en una afirmación de rendimiento o seguridad de un servicio público sin revisar el diseño y el despliegue.')

chapter('src/seed.ts: preparar una demostración reproducible', 'Los datos iniciales explican cómo probar funciones sin inventarlos cada vez.')
fileintro('src/seed.ts','Insertar cuentas, equipos y recorridos ficticios en una base vacía.','database.ts, hashPassword y conversiones de tiempo.','Una base nueva tiene personas y ejemplos para explorar todos los perfiles.')
h('La condición de entrada importa')
p('La función consulta cuántas cuentas hay y termina si ya existe alguna. No se ejecuta otra vez en cada recarga ni sobrescribe las reservas que hayas creado. Sus datos se insertan dentro de una transacción. Una semilla no es un sincronizador de cambios: editarla no actualiza por arte de magia una base ya poblada.')
h('Escribe las cuentas')
p('La lista accounts contiene nombre, identificador de acceso, perfil y entidad. El correo añade @demo.local. Cada cuenta obtiene una sal y un resumen propios para Demo2026!. Siete cuentas están vigentes o son internas; caducado tiene el contrato vencido desde el día anterior. Son ejemplos públicos de la demostración, no credenciales institucionales.')
h('Escribe el catálogo')
p('Cada elemento describe nombre, código, técnica, sala, texto, supervisión, color e icono. La centrífuga comienza averiada y tiene un parte asociado. Las clases de color y los nombres de icono deben coincidir con styles.css y el catálogo de ui.ts, respectivamente.')
h('Las fechas relativas y las reservas')
p('slot toma una fecha relativa a now, la convierte a día local de Madrid y añade una hora. La función insert escribe una fila de reserva. Para las sesiones finalizadas añade inicio y fin reales, ligeramente diferentes de las horas previstas, de modo que el informe no pueda confundirse con una suma de horas programadas.')
table(['Dato de ejemplo','Qué permite probar'],[['UCO mañana, microscopio','Consulta de próximas reservas y técnico asignado.'],['Externo a diez días, microscopio','Desplazamiento por prioridad UCO.'],['Sesiones finalizadas uno y dos días antes','Informe con consumo real; puede estar en el mes anterior al inicio de mes.'],['Una sesión en uso si el primer arranque es entre 08–20','Finalizar un uso real desde el perfil técnico sin esperar.'],['Centrífuga averiada','Reparación inmediata y reapertura del recurso.']])
h('Por qué la semilla inserta directamente')
p('Los ejemplos históricos no podrían crearse hoy mediante createBooking, que impide reservar en el pasado. La semilla prepara un estado ficticio inicial de forma explícita; las operaciones normales sí pasan por el módulo de reglas. No copies esta excepción para saltarte validaciones en una petición real.')
h('Comprobación incremental')
code("node --input-type=module -e \"import {openDatabase} from './src/database.ts'; import {seedDatabase} from './src/seed.ts'; const db=openDatabase(); seedDatabase(db); console.log(db.prepare('SELECT id,email,role FROM users').all()); db.close();\"", 'bash')
p('Debes ver ocho cuentas. Llamar dos veces a seedDatabase en esa misma conexión no debe duplicarlas. No imprimas passwordHash para comprobar que hay usuarios: las columnas públicas bastan.')

chapter('src/system.ts: implementar las reglas completas', 'El centro del proyecto: una operación pública representa una intención del usuario.')
fileintro('src/system.ts','Validar y ejecutar reservas, incidencias, contratos e informes.','Modelo, tiempo, acceso y transacciones disponibles.','Las funcionalidades pueden probarse sin HTML ni servidor HTTP.')
h('Cómo abordar un archivo de este tamaño')
p('No intentes memorizar sus 245 líneas. Divide la escritura en cuatro grupos: ayudas y permisos; disponibilidad y reservas; incidencias y uso; usuarios, informes y vistas. Escribe un método, localiza sus consultas en el esquema y explica qué cambiaría si apareciera un error en cada punto. Después compáralo con el anexo.')
h('Ayudas: requiredText y positiveId')
p('requiredText recibe unknown porque los datos externos no merecen una confianza previa. Primero exige string; después comprueba la longitud del texto recortado y lo devuelve limpio. El orden del operador || evita ejecutar trim sobre un número o una ausencia de valor. positiveId convierte a Number y exige un entero seguro positivo.')
source('src/system.ts',9,19)
p('La conversión numérica no es una validación JSON de todos los detalles: por ejemplo, Number(true) produce 1. El prototipo rechaza identificadores no enteros o no positivos, pero no exige aquí que el tipo original sea number. Si vas a endurecer la entrada, comprueba también typeof value y añade pruebas para booleanos y cadenas. No atribuyas a esta función una garantía que no implementa.')
h('Constructor, allow e identidad')
p('CictSystem recibe db y now. allow aplica assertAccess y después verifica el rol, permitiendo al administrador superar la restricción de perfil. actor debe venir de una sesión ya autenticada; no lo construyas a partir del userId enviado en un formulario. Los métodos privados no son rutas HTTP: sirven a las operaciones del módulo.')
table(['Ayuda privada','Lo que hace'],[['instrument','Valida identificador, busca un instrumento y devuelve 404 si falta.'],['booking','Hace la misma búsqueda para una reserva.'],['log','Inserta una descripción de actividad con actor y hora.'],['notify','Inserta un aviso para su destinatario; no abre una conexión SMTP.']])
h('plan: escribe la validación antes de la escritura')
steps('Obtén kind: por defecto experimento, y rechaza cualquier otro texto salvo mantenimiento.', 'Exige investigación UCO/externa para experimentos o perfil técnico para mantenimiento; admin conserva sus permisos.', 'Convierte y valida la franja con validateSlot.', 'Para investigadores, exige que el fin de la reserva quede dentro del contrato.', 'Busca el instrumento y rechaza un experimento si está averiado.', 'Consulta todas las citas activas del mismo instrumento que se solapan.', 'Calcula cuáles pueden ser desplazadas por prioridad UCO.', 'Si hay alguna incompatible que no pueda desplazarse, rechaza toda la operación.', 'Si hace falta técnico, elige uno activo sin ocupación incompatible.', 'Devuelve un plan con recurso, instantes, técnico y reservas a desplazar; todavía no escribas cambios.')
h('La consulta de solapamiento')
code("SELECT b.*, u.role AS ownerRole\nFROM bookings b\nJOIN users u ON u.id = b.userId\nWHERE instrumentId = ?\n  AND startsAt < ?\n  AND endsAt > ?\n  AND status IN ('confirmada', 'en_uso')", 'sql', 'La consulta de plan, distribuida para leerla')
p('El orden de los valores vinculados es instrumento, fin solicitado e inicio solicitado. La consulta pregunta si la reserva existente empieza antes de tu fin y termina después de tu inicio. No intercambies esos parámetros. JOIN incorpora el perfil del propietario para decidir la prioridad sin confiar en un dato enviado por el cliente.')
h('Prioridad UCO: todas las condiciones son necesarias')
bullets('La solicitud nueva es un experimento y su actor es UCO.', 'La cita anterior pertenece a un externo y también es de experimento.', 'La cita anterior sigue confirmada: no se desplaza una sesión ya iniciada.', 'Faltan estrictamente más de siete días de duración hasta el inicio de esa cita.')
p('Se comparan las longitudes de displaced y conflicts. Si no coinciden, alguna cita no puede sustituirse y se rechaza el conjunto. Con cero conflictos ambas longitudes son cero y el plan puede continuar. El administrador no se convierte en investigador UCO por tener más permisos: la prioridad depende del tipo de solicitante.')
p('Exactamente siete días protege la reserva externa. Se trata de una decisión documentada para el punto abierto de vuestra P2. DAY es una duración de 24 horas; esta comparación significa más de 168 horas, no contar siete cambios de fecha en un calendario.')
h('Asignación de técnicos')
p('Se consultan técnicos activos ordenados por id. Para cada candidato se comprueban sus intervalos confirmados o en uso, aunque sean de otro instrumento. Se considera disponible si todas sus citas incompatibles pertenecen al conjunto que esta misma operación va a desplazar. Esto evita rechazar al técnico que quedará libre al sustituir una reserva externa.')
p('En mantenimiento, un técnico solo programa su propia intervención; administración puede encontrar un técnico libre automáticamente. En experimentos que no lo requieren, technicianId queda null. No hay calendario de bajas ni especialidades en esta versión: la disponibilidad se simplifica a perfil activo, horario y ocupación.')
h('availability: informar sin guardar')
p('Utiliza plan y devuelve mensaje, número de desplazamientos y si se asignaría técnico. No inserta reservas ni avisos. La comprobación previa no bloquea la franja: createBooking debe repetirla. No implementes una confirmación que acepte simplemente el resultado anterior del navegador.')
h('createBooking: confirmar como una sola unidad')
steps('Valida el motivo antes de entrar en la transacción.', 'Dentro de la transacción vuelve a construir el plan.', 'Marca las citas desplazadas y avisa a sus propietarios.', 'Inserta la nueva reserva confirmada con el actor autenticado como propietario.', 'Convierte lastInsertRowid a number.', 'Añade confirmación y actividad.', 'Devuelve el id; transaction confirma todo o revierte todo.')
source('src/system.ts',89,104)
p('El id identifica la fila recién insertada, no su posición visual en una tabla. Si se produce un fallo al crear un aviso, no debe quedar confirmada una reserva sin su operación completa. La prueba de atomicidad simula precisamente ese fallo con un trigger de SQLite.')
h('cancelBooking: propiedad, estado y antelación')
p('Solo el propietario o administración puede cancelar. En mantenimiento, el propietario debe ser técnico si no es administrador. Se exige una cita confirmada cuyo inicio sea posterior a now. Después se compara la antelación con DAY: menos de 24 horas es facturable para experimentos; exactamente 24 no lo es. Se guarda fecha y marca, se avisa y se registra actividad.')
p('Una cancelación facturable no ejecuta un pago. El informe utilizará la duración prevista de esa cita en una columna separada. No borres la fila: perderías la evidencia de cancelación y el dato que necesita contabilidad.')
h('recordUsage: registrar hechos y evitar dobles usos')
steps('Exige técnico o administrador; si no es admin, comprueba que el técnico esté asignado.', 'Rechaza operaciones de uso sobre reservas de mantenimiento.', 'Para start, exige confirmada y hora actual dentro de la franja.', 'Comprueba que el instrumento no esté averiado y que equipo o técnico no tengan otra sesión real en curso.', 'Guarda actualStart y estado en_uso.', 'Para finish, exige un inicio real anterior y guarda actualEnd con estado finalizada.', 'Añade actividad sin permitir un estado arbitrario enviado por el cliente.')
p('El fin puede registrarse después de la franja prevista. El prototipo conserva el hecho real y bloquea otra sesión real incompatible mientras la anterior no se cierre. Una reserva futura puede estar planificada, pero no arrancará un uso real si el recurso continúa en uso. Para los equipos autónomos el administrador registra el uso en esta demostración.')
h('createIncident: bloquear sin borrar citas')
p('Se valida perfil y descripción. Dentro de una transacción se crea el parte, se marca el equipo como averiado, se buscan usuarios distintos con citas afectadas y se genera un aviso a cada uno. DISTINCT evita múltiples avisos iguales para una misma persona por tener varias reservas de ese equipo. Las citas se conservan y el mensaje explica que deben revisar el estado.')
h('resolveIncident: resolver la última avería relevante')
p('Solo técnico/admin. Se exige texto de resolución y un parte existente aún abierto. Se guarda su cierre y se busca cualquier otra incidencia abierta de ese instrumento. Solo si no queda ninguna se cambia a disponible y se avisa a usuarios con próximas citas confirmadas. Resolver un parte no equivale a resolver todos los del aparato.')
h('createExternal, contractDates y updateContract')
p('createExternal exige administrador, valida nombre, correo, empresa, contraseña y fechas, comprueba duplicidad e inserta siempre role externo. Aunque el cliente envíe role admin, el INSERT no lo utiliza. La contraseña inicial nueva requiere diez caracteres; la contraseña pública de la semilla es un ejemplo independiente de esas altas.')
p('contractDates interpreta el primer día a las 00:00 y el último hasta las 23:59:59.999 de Madrid. updateContract solo opera sobre cuentas de investigación UCO/externas, exige active booleano y elimina sus sesiones para aplicar inmediatamente el cambio. Se conserva la cuenta y sus referencias históricas.')
h('report: calcular consumo por periodo')
steps('Exige contabilidad/admin y convierte el mes en límites de instantes.', 'Consulta experimentos finalizados cuyo uso real se cruce con el mes.', 'Incluye además cancelaciones tardías cuya sesión prevista pertenezca a ese mes.', 'Agrupa con una clave userId:instrumentId.', 'Para cada uso real, suma min(finReal, finMes) − max(inicioReal, inicioMes).', 'Para cada cancelación tardía, suma la duración prevista de la reserva.', 'Convierte de milisegundos a horas, redondea a dos decimales y devuelve filas.')
code('const horasEnMes = (\n  Math.min(finReal, finMes) - Math.max(inicioReal, inicioMes)\n) / HOUR;', 'typescript', 'La operación de recorte, con nombres explicativos')
p('No sumes endsAt − startsAt para todos los casos: eso mediría tiempo reservado y no consumo real. Las sesiones en uso todavía no tienen fin y quedan fuera. Tampoco añadas mantenimiento al consumo de investigación ni conviertas las horas en euros sin una regla de tarifas acordada.')
h('readNotifications y snapshot')
p('readNotifications marca los avisos de la persona autenticada. snapshot consulta el estado visible: catálogo, reservas, incidencias, avisos, actividad y, solo para admin, cuentas. Para investigación y consulta, las reservas ajenas pierden nombre, empresa y motivo, y userId se sustituye por cero. La marca own se calcula antes de esa anonimización.')
p('El perfil técnico, contable y administrador conserva la información operativa prevista en el prototipo. Un array users vacío en otro perfil es deliberado. Ocultar un nombre con CSS no sería equivalente: seguiría dentro de la respuesta JSON si no se eliminase aquí.')
h('Comprobaciones que fijan este archivo')
table(['Prueba','Qué debe conservarse'],[['Solapamiento','Ninguna cita incompatible aceptada salvo prioridad permitida.'],['Técnicos','Dos equipos diferentes no utilizan el mismo técnico a la vez.'],['Atomicidad','Un fallo intermedio no deja un desplazamiento parcial.'],['Cancelación','La frontera de 24 horas no se redondea a días.'],['Avería','Varias incidencias requieren resolverlas todas.'],['Informe','Horas reales y cancelaciones no se confunden.'],['Privacidad','Los datos ajenos desaparecen del estado enviado, no solo de la pantalla.']])

chapter('src/server.ts: convertir operaciones en HTTP', 'Una ruta recibe una petición, no una persona ni un objeto ya validados.')
fileintro('src/server.ts','Arrancar Node, servir recursos y conectar HTTP con las operaciones.','Todos los módulos de servidor y los tres archivos públicos existen.','Puedes visitar el documento y llamar a la aplicación por HTTP.')
h('Primer bloque: importaciones y rutas de archivos')
p('Los módulos node:http, node:fs, node:path, node:url y node:module ya vienen con Node. ROOT se calcula a partir de la ubicación de server.ts, no de la terminal. Ese directorio sirve para localizar public, docs y data. Las funciones del dominio se importan de los archivos que has escrito antes.')
h('json: responder de forma uniforme')
p('La ayuda fija estado, Content-Type JSON y Cache-Control no-store, serializa con JSON.stringify y termina la respuesta. Si olvidas end, el navegador puede quedar esperando. Los datos se convierten a texto solo en la frontera HTTP; CictSystem trabaja con objetos y números.')
h('readBody: limitar y analizar la entrada')
steps('Exige Content-Type que comience por application/json.', 'Lee los fragmentos con for await y los acumula.', 'Rechaza un cuerpo que supere 16 KiB.', 'Analiza JSON y exige un objeto no nulo que no sea array.', 'Devuelve ese objeto; cada operación validará sus campos.')
p('El análisis JSON no prueba que startsAt sea una fecha o que el rol tenga permiso. Son comprobaciones distintas. En este prototipo se espera JSON válido y texto UTF-8 de tamaño reducido. Una implementación pública tendría que revisar más aspectos del transporte y de los límites bajo carga.')
h('cookieToken y csvCell')
p('cookieToken busca cict_session en la cabecera Cookie y extrae su valor. La cadena cict_session= tiene 13 caracteres; slice(13) elimina ese prefijo. No confundas la cookie completa con el token que Auth.session necesita resumir.')
p('csvCell convierte un valor a texto, antepone una comilla simple a comienzos que podrían interpretarse como fórmula en una hoja de cálculo y duplica las comillas internas. Después rodea la celda con comillas dobles. El CSV usa punto y coma, BOM UTF-8 y filas separadas por retorno de carro y salto de línea.')
h('createApplication: construir sin escuchar todavía')
steps('Escoge la ruta de SQLite y crea su directorio si hace falta.', 'Abre la base y aplica la semilla salvo que se haya desactivado.', 'Construye Auth y CictSystem con el mismo reloj.', 'Transforma app.ts, ui.ts y views.ts a JavaScript y guarda esos resultados.', 'Crea el servidor HTTP y sus manejadores.', 'Devuelve server, db, system y auth para que las pruebas puedan usar la aplicación.')
p('La función no llama por sí sola a listen. Esto permite a HTTP tests usar un puerto aleatorio y una base en memoria. El bloque final del archivo sí llama a listen cuando ejecutas directamente node src/server.ts. Comparar process.argv[1] con la URL del módulo distingue importar de ejecutar como entrada principal.')
h('Recursos públicos: una lista cerrada')
p('El servidor responde al documento raíz, tres módulos JavaScript, CSS, favicon y documentos enumerados. No convierte cualquier URL en una ruta del disco. De este modo una petición a /data/prototipo.sqlite o /src/auth.ts no descarga esos archivos. Los nombres de docs permitidos están en un array explícito.')
p('Los módulos JavaScript se transforman al construir la aplicación. Reinicia Node después de editar public/*.ts y recarga. HTML y CSS se leen al solicitarse y basta con recargar. node --watch vigila módulos del servidor importados; no debes suponer que recargará cualquier archivo leído mediante fs.')
h('Cabeceras de respuesta')
table(['Cabecera','Objetivo en este prototipo'],[['X-Content-Type-Options: nosniff','Evitar que el navegador adivine otro tipo de archivo.'],['X-Frame-Options: DENY','Evitar que se incruste en un marco.'],['Referrer-Policy: same-origin','Limitar la referencia al mismo origen.'],['Content-Security-Policy','Permitir recursos locales y restringir scripts/estilos incrustados.'],['Cache-Control: no-store en JSON','No conservar el estado autenticado en la caché habitual.']])
p('La política de estilos no permite style inline. Por eso el gráfico utiliza clases level-0 a level-10 en lugar de escribir una altura calculada en style="...". La estructura HTML sí contiene SVG constantes, cuyos atributos describen trazos y no ejecutan JavaScript.')
h('El recorrido de escritura, antes de cada ruta')
steps('Analiza URL, método y ruta.', 'Si es una escritura con Origin, comprueba que coincida con el origen HTTP local del Host.', 'Resuelve el acceso de login aparte, con límite de intentos por dirección.', 'Para las demás operaciones, extrae el token y obtiene una sesión vigente.', 'Si es escritura, compara X-CSRF-Token con el valor de la sesión.', 'Lee el cuerpo JSON y llama a la operación correspondiente.')
p('La comprobación de Origin permite herramientas de terminal que no lo envían; las escrituras autenticadas siguen exigiendo CSRF. Las cookies usan HttpOnly y SameSite=Strict, con duración de ocho horas. No se marca Secure porque este servidor de estudio utiliza HTTP en loopback. No extrapoles esa configuración a un despliegue público.')
h('Escribe las rutas por grupos')
table(['Grupo','Rutas y operaciones'],[['Acceso','POST login; GET session; POST logout.'],['Estado','GET state; devuelve snapshot adaptado.'],['Reservas','POST availability, bookings y bookings/:id/cancel.'],['Uso real','POST bookings/:id/start y /finish.'],['Incidencias','POST incidents y incidents/:id/resolve.'],['Cuentas','POST users y users/:id/contract.'],['Avisos','POST notifications/read.'],['Informes','GET reports y reports.csv con month en la consulta.']])
p('Las expresiones regulares de rutas capturan solo identificadores de dígitos y las acciones previstas. Los cuerpos se interpretan como la entrada de cada operación, pero esa aserción TypeScript no valida: la validación real permanece en las funciones llamadas.')
h('Errores y arranque')
p('El catch devuelve el status de DomainError y un mensaje legible. Los errores inesperados se registran en la terminal y se convierten en 500 con texto genérico. El arranque valida PORT, escucha en 127.0.0.1 y atiende SIGINT/SIGTERM para cerrar. Un error EADDRINUSE no implica que la base esté corrupta.')
h('Comprueba HTTP antes de la interfaz completa')
code('node src/server.ts\n# En otra terminal:\ncurl http://localhost:4173/health', 'bash')
p('Debes recibir {"ok":true}. Visitar la raíz debe cargar el HTML. Si app.ts sigue siendo el andamio export {}, todavía verás el estado inicial de la página: completa los archivos de interfaz antes de esperar los formularios.')

chapter('public/index.html: el documento de entrada', 'Veinte líneas que cargan el resto y ofrecen los puntos de montaje.')
fileintro('public/index.html','Crear el documento HTML inicial y sus contenedores accesibles.','El servidor sirve /, CSS y módulos públicos.','El navegador puede cargar recursos y JavaScript puede localizar #app y #modal.')
source('public/index.html')
h('Escríbelo de arriba abajo')
steps('Declara doctype y lang="es".', 'Configura UTF-8 para tildes, viewport para móvil, color de tema y descripción.', 'Enlaza /favicon.svg y /assets/styles.css.', 'Carga /assets/app.js como type="module".', 'Crea un enlace para saltar al contenido principal.', 'Añade #app con un estado de carga que después se sustituirá.', 'Añade #toast con role=status y aria-live=polite.', 'Añade el dialog #modal con aria-labelledby=dialog-title.', 'Cierra con noscript para explicar qué ocurre si no se ejecuta JavaScript.')
p('type=module permite import/export y se ejecuta después de analizar el documento; el código puede encontrar los elementos definidos debajo. El navegador pide app.js porque eso es lo que entrega el servidor. No cambies la ruta por src/server.ts ni intentes abrir index.html directamente desde el explorador de archivos.')
h('Accesibilidad que tiene una función concreta')
p('aria-live hace que los cambios de aviso puedan anunciarse sin mover el foco. dialog-title se creará al abrir un formulario. El enlace de salto evita recorrer siempre la barra lateral. noscript es texto real alternativo, no una prueba de permisos ni un reemplazo de la interfaz completa.')
h('Comprueba el resultado')
p('En las herramientas de red deben aparecer respuestas para el documento, CSS y módulos JavaScript, con tipos de contenido adecuados. Un 404 suele indicar una ruta distinta de la que server.ts permite. Un bloqueo CSP suele indicar un recurso externo o código/estilo inline que la política no autoriza.')

chapter('public/ui.ts: formatos, iconos y HTML seguro', 'Funciones pequeñas compartidas por todas las pantallas.')
fileintro('public/ui.ts','Dibujar iconos constantes, escapar datos y formatear presentación.','Conoces funciones flecha, objetos e Intl.','Las vistas tienen un vocabulario visual coherente sin repetir conversiones.')
h('paths e icon')
p('paths es un diccionario de nombres a fragmentos SVG constantes: microscope, calendar, alert, etc. icon crea un elemento svg con el fragmento elegido y usa atom como alternativa. Los trazos utilizan currentColor para heredar el color de CSS. aria-hidden evita que un dibujo decorativo repita el texto del botón.')
p('Los nombres y clases de icono que se pasan desde esta aplicación proceden de su propio catálogo. No conviertas icon en una función que inserte SVG arbitrario enviado por una cuenta. Las cadenas confiables del programa y los datos de usuarios no se manejan igual.')
h('escape: el límite antes de innerHTML')
source('public/ui.ts',34,34)
p('escape convierte &, <, >, comillas dobles y simples en entidades HTML. Se utiliza con nombres, descripciones, valores de campos y mensajes que se interpolan en una plantilla. Sin esa conversión, un texto que contenga una etiqueta podría convertirse en estructura en lugar de mostrarse como texto.')
code("escape('<b>Texto</b>')\n// &lt;b&gt;Texto&lt;/b&gt;", 'typescript')
h('date, time, dateKey y hours')
table(['Función','Uso y razón'],[['date','Presentación española con zona Madrid y opciones ajustables.'],['time','Solo hora/minuto en ciclo 24 h.'],['dateKey','Clave local AAAA-MM-DD, útil para agrupar reservas por día.'],['hours','Número con formato español, hasta dos decimales y sufijo h.'],['initials','Iniciales de dos palabras para el avatar.']])
p('Separar la clave de fecha de la presentación evita comparar textos como «24 nov». dateKey produce una forma ordenada; date produce algo legible. Ninguna función de aquí sustituye a parseLocalDateTime del servidor: formatear no es validar.')
h('Etiquetas y piezas de presentación')
p('roleName y statusName traducen estados internos. badge construye una etiqueta con su clase y texto escapados. empty devuelve una pantalla vacía explicativa. button produce botones con data-action y, cuando corresponde, data-id. El clic todavía no hace nada: lo escuchará app.ts.')
h('Ejercicio de lectura')
p('Localiza un nombre de instrumento en views.ts. Sigue cómo se pasa por escape y cómo el icono se obtiene por nombre. Después imagina una descripción que contiene <script>: explica por qué debe verse como texto y qué ocurriría si interpolaras esa cadena sin escapar.')

chapter('public/views.ts: escribir todas las pantallas', 'Este archivo describe qué HTML corresponde a un estado; no envía peticiones.')
fileintro('public/views.ts','Generar el HTML de acceso, estructura, panel y funcionalidades.','ui.ts y los tipos del modelo disponibles.','Puedes representar cada pantalla a partir de Snapshot.')
h('Empieza por tipos y permisos de presentación')
p('Filters contiene búsqueda, categoría, estado, alcance y mes. canBook, canMaintain, canReport y canIncident deciden qué botones mostrar. Estas ayudas mejoran la interfaz; no conceden permisos al servidor. Aunque alguien fabrique un botón en su navegador, system.ts debe seguir rechazando la operación.')
p('La ayuda option compone cada opción de un select, escapa valor y etiqueta y añade selected si coincide con el filtro. staff agrupa los perfiles con acceso operativo a vistas del centro; no sustituye los permisos del servidor.')
h('brand y loginView')
p('brand construye el símbolo y la palabra SGCICT. loginView devuelve la pantalla inicial con dos columnas, formulario y botones de demostración. Los ids email, password y login-form son contratos con app.ts. Los data-profile de los botones coinciden con la parte anterior a @demo.local de las cuentas de la semilla.')
image('docs/capturas/01-acceso.png','loginView: formulario real y accesos de demostración.',250)
h('shell: la estructura compartida')
steps('Define las entradas de navegación base.', 'Añade informes para contabilidad/admin y usuarios para admin.', 'Calcula el número de avisos no leídos.', 'Construye barra lateral, ayuda, institución y enlaces de documentación.', 'Construye cabecera, fecha, campana y perfil.', 'Deja un contenedor #page dentro de #main para el contenido de la ruta.')
p('El hash de la dirección cambia la página de la interfaz. El servidor sigue entregando el mismo documento raíz. aria-current marca la navegación activa y el botón móvil controla la barra lateral con aria-expanded y aria-controls. No conserves varios elementos con el mismo id main cuando sustituyas la pantalla de acceso.')
h('heading y sectionHead')
p('Estas ayudas privadas uniforman títulos, descripciones y acciones. Se reutilizan porque concentran estructura repetida; no necesitan convertirse en clases. Las cadenas que contienen datos se escapan antes de insertarse.')
h('bookingRows y bookingsTable')
p('bookingRows calcula botones por estado y perfil: cancelar una cita futura propia/admin, iniciar uso durante su franja o finalizar una sesión en uso. El servidor repetirá las reglas. La fila muestra instrumento, fecha, técnico, estado y datos de persona solo cuando el estado recibido los incluye.')
p('bookingsTable escribe cabeceras, filas y contenedor desplazable; si no hay resultados muestra empty. El modo compact reduce columnas en el panel. El texto oculto «Acciones» mantiene una cabecera accesible aunque visualmente esa columna solo tenga botones.')
h('overview: números calculados a partir del estado')
p('El panel cuenta equipos operativos, citas de hoy, próximas reservas relevantes e incidencias abiertas. Para un investigador, próximas se limita a sus citas; el personal con acceso operativo ve la actividad del centro. No hay métricas aleatorias ni números fijos de marketing.')
p('El gráfico considera cinco días, suma horas previstas y compara con doce horas por instrumento. La altura se agrupa en niveles de 0 a 10: es aproximada, como dice la leyenda. El número sobre cada barra es cantidad de citas. Los días sin citas usan level-0 y no simulan ocupación.')
h('catalog e instrumentCard')
p('catalog filtra por técnica y por texto de nombre/código/categoría. instrumentCard compone ilustración, estado, sala, descripción y próxima reserva. Un mantenimiento futuro no convierte el equipo en averiado; el distintivo «En mantenimiento» se calcula si una reserva técnica coincide con now. La disponibilidad para una franja concreta se comprueba en el servidor al abrir el formulario.')
image('docs/capturas/03-catalogo.png','Catálogo: una tarjeta enlaza datos, etiquetas, iconos y acciones.',260)
h('bookings')
p('Filtra por todas/mías y por estado, ordena las citas por inicio y utiliza bookingsTable. La pantalla explica privacidad y la política de cancelación. No elimina del array las reservas ajenas para ocultarlas: conserva la ocupación anonimizada que el servidor permite conocer.')
h('incidents')
p('Separa partes abiertos y resueltos. Una tarjeta abierta muestra seguimiento y, con permisos técnicos, el botón de reparación. La resolución se muestra como texto escapado y con saltos de línea conservados por CSS. No actualiza por su cuenta el equipo: solicita una operación desde app.ts.')
h('reports')
p('Comprueba el permiso de presentación, ofrece selector mensual y enlace CSV, calcula resúmenes de las filas y muestra carga cuando rows es null. Distinguir null de [] importa: null significa todavía sin respuesta; [] significa respuesta válida sin consumo.')
h('users')
p('Solo administración recibe esta pantalla con el listado. Determina acceso según estado y contrato, muestra perfil interno sin fecha contractual cuando corresponde y añade edición para investigadores. Los botones de alta y contrato no incluyen una elección libre de rol.')
h('inbox, guide y contact')
table(['Vista','Qué escribir'],[['inbox','Lista de avisos propios, distinción leído/nuevo y botón para marcar todos.'],['guide','Diagrama explicativo y ocho enlaces a documentos existentes.'],['contact','Información ficticia identificada como ejemplo y horario del centro.']])
p('El dominio .invalid de contacto evita presentar una dirección ficticia como un canal real. Los enlaces a documentos pasan por la lista cerrada de server.ts. Añadir un documento nuevo exige actualizar tanto la vista como la lista si quieres servirlo desde la web.')
h('Cómo escribir plantillas grandes sin perderte')
steps('Empieza con la estructura semántica: section, h2, table o form según corresponda.', 'Añade los datos escapados y recorre listas con map(...).join(\'\').', 'Añade las clases de CSS.', 'Añade data-action y data-id solamente donde una interacción lo necesite.', 'Comprueba estados con contenido, sin resultados y sin permisos.', 'Compara el resultado con la captura; deja la lógica de petición en app.ts.')
note('join vacío tiene una razón', 'map devuelve un array. Al interpolar ese array sin join, JavaScript puede introducir comas entre fragmentos HTML. Usa join(\'\') para concatenar las tarjetas o filas sin separadores visibles.')

chapter('public/app.ts: conectar formularios, estado y peticiones', 'Aquí conviertes las pantallas estáticas en una aplicación interactiva.')
fileintro('public/app.ts','Gestionar sesión de interfaz, navegación, formularios y llamadas HTTP.','index.html contiene los ids esperados y las vistas generan HTML válido.','Un clic produce una operación real y la pantalla vuelve a reflejar la base.')
h('Las variables iniciales y lo que no guardan')
p('root, modal y toastElement referencian nodos que ya existen en index.html. snapshot empieza en null y representa ausencia de estado autenticado. csrf guarda la protección de escritura de la sesión. reportRows empieza en null hasta recibir el informe. filters mantiene elecciones de presentación. No se utiliza localStorage para decidir permisos ni para guardar reservas.')
p('currentPage admite solo los hashes de pageNames y cae a overview cuando no reconoce uno. errorText convierte una excepción conocida a texto útil. toastTimer, opener y reportRequest tienen responsabilidades diferentes: temporizador del aviso, recuperación de foco y protección frente a respuestas antiguas de informes.')
h('toast: avisar sin interrumpir el trabajo')
p('Cancela el temporizador anterior, establece textContent, marca la clase visible y programa su retirada. textContent muestra el mensaje como texto sin interpretarlo como HTML. El elemento ya tiene aria-live desde index.html. No lo utilices como sustituto del error de un campo que el usuario necesita corregir dentro de un formulario.')
h('request<T>: una sola forma de hablar con el servidor')
steps('Crea AbortController y un límite de espera de quince segundos.', 'Usa GET si no hay body y POST cuando sí lo hay.', 'Incluye credenciales del mismo origen y, en POST, JSON y X-CSRF-Token.', 'Espera fetch y analiza la respuesta JSON.', 'Si el status no es correcto, distingue una sesión perdida y construye Error con el mensaje recibido.', 'Traduce fallos de conexión y de tiempo a mensajes legibles.', 'Cancela siempre el temporizador en finally.')
source('public/app.ts',22,43)
p('El parámetro genérico T describe lo que el llamador espera recibir; no revisa la estructura del JSON en ejecución. La aplicación es quien conoce sus respuestas del servidor. No uses esa aserción para afirmar que un servicio externo devuelve datos válidos sin comprobarlos.')
h('renderPage y renderShell')
p('renderPage elige una función de views según currentPage y escribe su resultado en #page. Antes de hacerlo, si estás filtrando, conserva el id del campo y la selección del cursor para restaurar el foco después. Sin esto, reconstruir el buscador al escribir podría hacerlo perder el foco tras cada letra.')
p('renderShell sustituye la estructura completa cuando cambia la página o se actualiza el estado. Si snapshot es null, devuelve el acceso. El diálogo se mantiene fuera de #app en index.html; no desaparece por sustituir la estructura del espacio de trabajo.')
h('loadReport: evitar que gane una respuesta antigua')
p('Cada petición aumenta reportRequest. Guarda el número y el mes solicitados, muestra el estado de carga y espera el informe. Al llegar, solo lo aplica si su número sigue siendo el último y continúas en informes. Sin esa comprobación, al cambiar deprisa de noviembre a diciembre podría llegar después noviembre y sobrescribir la pantalla de diciembre.')
h('refresh: volver a la fuente de datos')
p('Después de una operación correcta se consulta state y se representa el estado resultante. Si estás en informes también se actualiza su consulta. No basta con añadir una tarjeta local al array: una operación puede haber desplazado otras reservas, creado avisos o bloqueado un equipo. El servidor conoce esos efectos completos.')
h('openDialog y formEnd')
p('openDialog recuerda el elemento que tenía el foco, compone título y contenido y llama a showModal. formEnd añade el error y las acciones comunes y cierra el formulario que abrió cada constructor. Ese reparto obliga a que cada constructor abra exactamente un form válido: comprueba las etiquetas cuando lo modifiques.')
h('Escribe los seis constructores de formulario')
table(['Función','Qué datos crea y qué reglas ayuda a expresar'],[['bookingDialog','Equipo, tipo, día, inicio, fin y motivo. Distingue mantenimiento y bloquea la elección de averiados para experimentos.'],['incidentDialog','Equipo y descripción. Explica que el bloqueo y los avisos son efectos de guardar.'],['resolveDialog','Parte seleccionado y resolución. Informa de que otras averías abiertas mantienen el bloqueo.'],['userDialog','Nombre, correo, entidad, contraseña inicial y vigencia. No ofrece alta como administrador.'],['contractDialog','Fechas y cuenta habilitada para un investigador existente.'],['confirmationDialog','Cancelación, inicio o fin de uso; muestra contexto y el efecto antes de confirmar.']])
h('bookingInput: transformar un formulario')
p('FormData recoge valores por name, no por id. instrumentId se convierte a número; día y horas se combinan como AAAA-MM-DDTHH:mm. La fecha se envía sin una conversión automática a la zona del visitante: time.ts la interpretará como Madrid. kind procede del campo oculto, pero el servidor comprueba los valores admitidos.')
source('public/app.ts',122,125)
h('Delegación de clics')
p('Se añade un manejador al document y se busca el elemento más cercano con data-action. Así también funciona cuando haces clic en el icono que contiene un botón y cuando la pantalla se acaba de reconstruir. Asignar listeners individuales a cada tarjeta después de cada render sería más fácil de olvidar o duplicar.')
table(['Acción','Efecto del manejador'],[['demo-login','Rellena credenciales ficticias y usa requestSubmit para seguir el formulario de acceso.'],['logout','Solicita cierre, limpia sesión local y vuelve al acceso.'],['book / maintenance','Abre el mismo constructor de reserva con distinto tipo.'],['incident / resolve','Abre alta o resolución del parte seleccionado.'],['user / contract','Abre alta de externo o cambio de vigencia.'],['cancel / start / finish','Pide confirmación de la operación.'],['category / scope','Cambia filtros locales y vuelve a representar.'],['read','Marca avisos propios y refresca.'],['menu','Alterna sidebar-open y aria-expanded.'],['availability','Envía una consulta sin mutación y escribe el resultado en el diálogo.']])
h('El manejador submit')
steps('Atiende solo login-form y operation-form; cancela el envío HTML tradicional.', 'Evita doble envío con data-busy, desactiva el botón y limpia errores.', 'En acceso, envía credenciales, guarda csrf, cambia la ruta y carga el estado.', 'En operaciones, convierte campos con FormData y escoge el endpoint según data-operation.', 'Para el checkbox de contrato, convierte on a un booleano real.', 'Si termina bien, cierra el diálogo, refresca y muestra un aviso.', 'Si falla, conserva el formulario y muestra el error en su zona.', 'En finally restaura el botón y el indicador de envío.')
p('No hagas una segunda reserva como respuesta automática a un fallo de red: la primera petición podría haber sido aceptada y haberse perdido solo su respuesta. En esta demostración el estado se consulta para aclarar el resultado. Un servicio de mayor alcance puede necesitar claves de idempotencia para operaciones repetibles.')
h('input, change, close y hashchange')
p('input actualiza la búsqueda y limpia una disponibilidad que ya no corresponde a los campos actuales. change ajusta estado o mes. close devuelve el foco al elemento que abrió el diálogo si sigue conectado, o al contenido principal. Un clic fuera de su rectángulo puede cerrarlo; Escape lo gestiona el diálogo nativo. hashchange representa la nueva página y pide informe si procede.')
h('El arranque final del módulo')
p('Al cargar, app.ts consulta session. Si hay una sesión válida, obtiene csrf y refresca. Si no la hay, muestra loginView. Se usa await en el nivel superior porque se ejecuta como módulo. No arranques con un usuario administrador inventado en una variable para saltarte este recorrido.')
h('Comprobación de una reserva de principio a fin')
steps('Abre el acceso como UCO.', 'Busca la balanza y pulsa Reservar.', 'Elige un día futuro libre y un motivo.', 'Comprueba disponibilidad y confirma.', 'Observa en la pestaña de red un POST bookings y un GET state posterior.', 'Recarga el navegador: la reserva debe seguir ahí porque se guardó en SQLite.')

chapter('public/styles.css: construir el diseño completo', 'Una hoja organizada por responsabilidades, con variables y adaptación real a móvil.')
fileintro('public/styles.css','Definir identidad visual, disposición, componentes, estados y tamaños de pantalla.','Las vistas usan las clases descritas en sus plantillas.','La misma aplicación se puede usar en escritorio y en una pantalla de 390 px.')
h('Cómo escribir una hoja grande sin mezclar responsabilidades')
p('La hoja está dividida por comentarios numerados. Escribe primero base y controles, después estructura y acceso, después cada pantalla y, al final, ajustes de móvil. Compara al menos una pantalla con datos, un diálogo abierto y un estado vacío. Una regla de estilo no debe cambiar un permiso de negocio.')
h('Bloque 01: variables y base')
source('public/styles.css',1,12)
p('--ink, --text y --muted dan jerarquía al texto. --forest y --green definen la identidad; --lime actúa de acento. --canvas y --white separan fondo y paneles. --line, --radius y --shadow evitan repetir los mismos criterios por toda la hoja. var(--forest) utiliza la variable; no copia su valor en un segundo lugar.')
p('box-sizing:border-box hace que padding y borde entren en el ancho declarado. El body elimina margen del navegador y establece tipografía del sistema. No hay descargas de fuentes. Los iconos comparten tamaño y trazo; los enlaces heredan color cuando el diseño no pide otro.')
h('Estados, controles y clases reutilizables')
table(['Selector o grupo','Qué resuelve'],[['.button, .primary, .secondary, .small, .full','Acción común y variantes. Evita definir un botón nuevo desde cero en cada vista.'],['.icon-button, .text-button, .text-link','Acciones discretas, con o sin texto visible.'],[':focus-visible, .skip-link','Foco de teclado y salto al contenido.'],['.sr-only','Texto para accesibilidad que no ocupa espacio visible habitual.'],['.mint, .lavender, .peach, .blue, .rose, .sand','Paletas de tarjetas, supervisión y recursos.'],['.badge-*','Estado con texto y punto: el color no es la única indicación.']])
p('Las transiciones cambian presentación y no ejecutan una operación. Deshabilitar un botón lo atenúa y señala espera; app.ts decide cuándo poner disabled. Un foco visible ayuda al uso por teclado y no debe eliminarse sin otra señal equivalente.')
h('Bloque 02: acceso y dibujo científico')
p('.login-layout organiza dos columnas. .login-story contiene identidad y relato; .login-panel centra el formulario. .science-art, .art-orbit, .art-core y .art-node dibujan una composición con bordes, transformaciones e iconos SVG. Son recursos de código, no imágenes descargadas.')
p('Los labels y campos tienen separación consistente. .form-error solo aparece si contiene texto. La cuadrícula .demo-accounts ofrece cuatro entradas y .demo-note explica datos ficticios y simulaciones. En móvil desaparece la ilustración secundaria y se reduce la composición al contenido necesario.')
h('Bloque 03: barra lateral, cabecera y contenido')
p('.sidebar ocupa una franja fija a la izquierda y puede desplazarse en vertical si falta altura. .workspace-main deja ese espacio con margin-left. .topbar distribuye navegación y perfil. .workspace #main limita el ancho y añade márgenes interiores únicamente dentro del espacio autenticado; así no aplica esos márgenes por accidente a la pantalla de acceso.')
p('Las clases active de navegación, nav-count y notification-dot expresan estados calculados por la aplicación. El footer no sustituye la información importante de la página: es una referencia de contexto y zona horaria.')
h('Bloque 04: panel, tablas y gráfico')
p('.stats-grid utiliza cuatro columnas y pasa a dos cuando falta ancho. .dashboard-columns combina tablas y panel lateral; sus hijos deben poder encogerse. .table-scroll limita el desplazamiento horizontal al área de la tabla. Tiene position:relative para que el texto accesible posicionado dentro no amplíe el documento móvil.')
p('Las alturas del gráfico se expresan como clases level-0 hasta level-10. Es una escala aproximada de capacidad, sin style inline, compatible con la política CSP del servidor. .activity-list y .featured-list representan listas distintas, aunque compartan el criterio de separadores y tamaños.')
h('Bloque 05: catálogo')
p('.catalog-toolbar contiene búsqueda y recuento. .filter-chips distribuye categorías y marca la selección. .instrument-grid muestra tres tarjetas en pantallas amplias, dos en intermedias y una en las pequeñas. Cada .instrument-art incluye color, código, técnica e icono; .instrument-info reúne datos y acción.')
p('El estado averiado no se simula bajando opacidad: views.ts decide la etiqueta y si ofrece reservar. CSS solo lo presenta. Las descripciones admiten diferentes longitudes; revisa alturas y envoltura para no hacer que el botón salte fuera de la tarjeta.')
h('Bloque 06: pantallas restantes')
table(['Grupo','Elementos principales'],[['Reservas','.info-strip, .table-toolbar, .segmented, .inline-label y .footnote.'],['Incidencias','.incident-summary, .incident-grid, .incident-card y .resolution.'],['Informes','.report-period, .report-stats y .report-stat.'],['Avisos','.notification-item, .unread y .unread-label.'],['Guía','.architecture-banner, .architecture-flow, .guide-grid y .guide-card.'],['Contacto','.contact-layout, .contact-visual y .contact-details.'],['Sin resultados','.empty-state con explicación y posible acción.']])
h('Bloque 07: diálogo y estados transitorios')
p('dialog limita ancho y altura y puede desplazarse si el contenido no cabe. ::backdrop oscurece el fondo. .form-columns reparte dos campos relacionados. .availability.success y .failure presentan el resultado de la consulta previa. #toast usa posición fija, opacidad y transformación para aparecer sin reorganizar toda la página.')
p('La carga usa una animación circular. Los mensajes y el diálogo siguen siendo HTML real, con roles y labels; el diseño no tiene que dibujar texto en un canvas para que se vea bien.')
h('Bloque 08: contraste, puntos de corte y movimiento')
table(['Condición','Cambios principales'],[['Más de 1700 px','Más espacio y un banner algo mayor.'],['Hasta 1280 px','Barra lateral más estrecha, catálogo de dos columnas y guía más compacta.'],['Hasta 1020 px','Panel reorganizado, indicadores en dos columnas y simplificación de adornos.'],['Hasta 760 px','Barra lateral fuera de pantalla, botón de menú, cabecera compacta y secciones apiladas.'],['Hasta 430 px','Catálogo de una columna y ajustes de diálogos y resúmenes.'],['prefers-reduced-motion','Se eliminan animaciones y transiciones.'],['Impresión','Se ocultan navegación y acciones, y se conserva contenido.']])
p('Una media query cambia reglas según la pantalla, no según el rol. Los ajustes finales del banner móvil colocan su ilustración como decoración absoluta para que no robe ancho al texto. No soluciones un desbordamiento del contenido con overflow-x:hidden en todo el body: podrías esconder controles en lugar de permitir utilizarlos.')
h('Comprobación visual mínima')
steps('A 1440 px: revisa barra lateral, cuatro indicadores y catálogo.', 'A 390 px: comprueba título, botón principal, menú y lectura sin desplazamiento horizontal global.', 'Desplaza una tabla dentro de su área.', 'Abre un diálogo y navega con Tab.', 'Activa preferencia de movimiento reducido y revisa que la información siga presente.', 'Prueba un nombre o descripción largos; deben envolverse y continuar legibles.')
image('docs/capturas/05-movil.png','Referencia móvil a 390 × 844: el documento no desborda; las tablas conservan su propio desplazamiento.',310)

chapter('public/favicon.svg: el detalle del navegador', 'Un archivo de texto vectorial, no una base de datos ni una fotografía.')
fileintro('public/favicon.svg','Mostrar el símbolo del proyecto en la pestaña.','index.html enlaza /favicon.svg y el servidor lo sirve.','La pestaña conserva la identidad del prototipo.')
p('La raíz svg declara el espacio de nombres y viewBox 0 0 64 64. Un rect dibuja el fondo redondeado. Dos ellipse con transformaciones dibujan órbitas y un circle marca el centro. Los colores se escriben como valores hexadecimales y no dependen de styles.css porque este SVG se solicita como recurso separado.')
p('Puedes distribuir el contenido original de una línea en varias líneas para estudiarlo, sin cambiar los atributos. Si modificas el archivo y el navegador no actualiza el icono inmediatamente, revisa su caché antes de modificar las rutas del servidor.')
source('public/favicon.svg')
h('Ejercicio')
p('Cambia solo el color del círculo central, recarga y verifica el icono. Después revierte el cambio. La función de esta prueba es distinguir un recurso estático de la lógica TypeScript que necesita reiniciar el servidor.')

chapter('tests/system.test.ts: verificar las reglas', 'Pruebas que saben qué resultado esperan, con reloj y base propios.')
fileintro('tests/system.test.ts','Comprobar acceso, tiempo y operaciones del módulo de reglas.','CictSystem, Auth y semilla completos.','Un comando reproduce casos normales y límites sin navegador.')
h('Importaciones y fixture')
p('Se utilizan node:test y assert/strict, incluidos en Node. fixture crea una base en memoria, fija now a un instante de Madrid, inserta la semilla y registra db.close al terminar. Devuelve ayudas para obtener usuarios, construir entradas, buscar reservas y avanzar el reloj. Cada prueba recibe una base distinta.')
source('tests/system.test.ts',1,27)
p('input produce por defecto una sesión futura de balanza. Modificar sus argumentos permite construir un caso técnico o un límite horario sin duplicar todo el objeto. booking lee el estado guardado para verificar efectos; setNow cambia la respuesta del reloj que utiliza el sistema.')
h('Una prueba se escribe en tres fases')
steps('Preparar: crea el escenario y los valores necesarios.', 'Actuar: llama a una operación pública.', 'Comprobar: compara el resultado o la excepción con lo esperado.')
code("test('Protege la primera cita', t => {\n  const f = fixture(t);\n  f.system.createBooking(f.user(2), f.input());\n  assert.throws(\n    () => f.system.createBooking(f.user(2), f.input()),\n    /ocupada/\n  );\n});", 'typescript', 'El patrón de un caso de conflicto, con formato expandido')
p('La función flecha dentro de assert.throws es necesaria: permite a la aserción ejecutar y capturar la excepción. Si llamas a la operación antes de pasarla, la excepción escaparía antes de entrar en la aserción.')
h('Qué casos escribir primero')
table(['Grupo','Casos que debes poder explicar'],[['Acceso','Contraseña incorrecta, contrato vencido, cierre y caducidad.'],['Tiempo','Verano/invierno, fecha imposible, intervalos adyacentes.'],['Reservas','Horario permitido, pasado, contrato, primera UCO y varias reservas.'],['Prioridad','Más de siete días, igualdad exacta y menos de siete.'],['Técnicos','Dos ocupados y recursos distintos compartiendo sala.'],['Atomicidad','Fallo del aviso revierte todos los cambios de la operación.'],['Cancelación','Veinticuatro horas exactas, menos y reserva ajena.'],['Incidencias','Bloqueo y avisos; dos partes abiertos; reparación sin permisos.'],['Mantenimiento','Conserva citas, ocupa técnico y no repara por programarlo.'],['Uso e informe','Inicio/fin válidos, recorte de mes y cancelación separada.'],['Privacidad y usuarios','Datos ajenos omitidos, alta, contrato e invalidación de sesión.']])
h('La prueba de atomicidad no es decorativa')
p('Se crea un trigger temporal que falla al insertar un aviso. Después se solicita una operación que desplazaría una cita. El resultado esperado es que esa cita siga confirmada y que no aumente el número de reservas. Así se verifica la transacción a través de un fallo intermedio real, no solo que exista una llamada a COMMIT.')
h('El reloj y la sesión de ejemplo en uso')
p('La semilla puede incluir un uso real en curso. Antes de avanzar cinco días para probar otro inicio, el caso de uso real lo termina. Dejarlo abierto y esperar un técnico libre sería contradecir la protección del sistema. No cambies la lógica de producción para acomodar una preparación de prueba incorrecta.')
h('Ejecuta y lee el resultado')
code('node --test --test-isolation=none tests/system.test.ts\nnode --test --test-isolation=none --test-name-pattern="Prioridad" tests/system.test.ts', 'bash')
p('La primera orden ejecuta los 28 casos del archivo original. La segunda limita por nombre. Un test que falla debe indicarte qué regla o preparación contradice el esperado. La suite no demuestra ausencia de todo error ni reemplaza revisar escenarios que todavía no tienen caso.')

chapter('tests/persistence.test.ts: cerrar y volver a abrir', 'Demostrar persistencia exige salir de la conexión en memoria.')
fileintro('tests/persistence.test.ts','Verificar que reservas y sesiones sobreviven a otra conexión.','La semilla y los módulos de acceso y reglas funcionan.','La prueba distingue estado persistido de objetos que solo viven en memoria.')
h('Cómo escribir el recorrido')
steps('Crea un directorio temporal con mkdtempSync y una ruta SQLite dentro.', 'Abre la primera conexión, inserta datos y crea una sesión UCO.', 'Crea una reserva por la operación pública, no por un objeto de interfaz.', 'Cierra la primera conexión.', 'Abre de nuevo el mismo archivo y llama a la semilla.', 'Comprueba que siguen siendo ocho cuentas: no se duplicaron.', 'Comprueba que la sesión y la reserva siguen presentes.', 'Cierra la segunda conexión y elimina únicamente el directorio temporal creado por la prueba.')
p('Si usaras :memory: para ambas conexiones, la segunda sería una base nueva. Si no cerraras la primera, no demostrarías el mismo recorrido de reapertura. La limpieza se limita a una ruta temporal propia; no dirige rm hacia data/prototipo.sqlite ni toca el servidor que tengas abierto.')
source('tests/persistence.test.ts',12,27)
h('Comprobación')
code('node --test --test-isolation=none tests/persistence.test.ts', 'bash')
p('El resultado original contiene un caso superado. Esta prueba es pequeña, pero cubre una garantía importante que un clic con el navegador abierto no comprobaría por sí solo.')

chapter('tests/http.test.ts: verificar la frontera web', 'Además de reglas correctas hacen falta rutas, cookies y respuestas correctas.')
fileintro('tests/http.test.ts','Ejercitar el servidor por HTTP real con un puerto temporal.','createApplication debe poder construirse sin arrancar la instancia principal.','Se verifican transporte, acceso, errores y recursos públicos.')
h('Construir un servidor de prueba')
p('createApplication recibe una base en memoria y un reloj fijo. listen(0, 127.0.0.1) pide al sistema un puerto libre; address obtiene el número elegido. Esto evita competir con tu aplicación en 4173. Al terminar se cierra el servidor y su conexión.')
h('La ayuda call y las credenciales de sesión')
p('call utiliza fetch incluido en Node y añade Cookie y CSRF cuando existen. En este entorno Node no conserva automáticamente las cookies de las peticiones del test como lo haría un navegador. Por eso, después del login se toma Set-Cookie y se guarda su primer componente para enviarlo de vuelta.')
h('Las ocho subpruebas')
steps('Pedir state sin sesión devuelve 401; pedir el documento es público e incluye CSP.', 'Login genera cookie HttpOnly/SameSite y un token CSRF.', 'Una escritura sin CSRF válido o con otro Origin devuelve 403.', 'Crear una reserva válida devuelve 201 y repetir conflicto, 409.', 'Campos ausentes o mes inválido devuelven 400.', 'El CSV se puede descargar y ni código privado ni SQLite se publican.', 'Los tres recursos del navegador se sirven como JavaScript y escape convierte HTML a texto.', 'Cerrar sesión hace que su cookie deje de servir para consultar estado.')
p('El ejecutor cuenta el contenedor principal y sus ocho subpruebas como nueve resultados. Junto con 28 casos de reglas y uno de persistencia produce los 38 resultados registrados en la documentación del prototipo. No los interpretes como 38 funciones de negocio distintas.')
h('Comprobación')
code('node --test --test-isolation=none tests/http.test.ts', 'bash')
p('Si el entorno impide abrir puertos, puede aparecer listen EPERM. Es una restricción del entorno de ejecución, distinta de un conflicto EADDRINUSE. Ejecutar solo las pruebas del dominio no sustituye las comprobaciones HTTP; registra la limitación o utiliza un entorno con loopback permitido.')

chapter('scripts/check.ts: una comprobación rápida y honesta', 'Sirve para detectar sintaxis y construcción; no es el compilador de tipos.')
fileintro('scripts/check.ts','Transformar los .ts y construir la aplicación con una base temporal.','Todos los directorios de código existen.','Una orden detecta errores sintácticos o un esquema que ya no se puede construir.')
source('scripts/check.ts')
p('Se enumeran src, public, tests y scripts, se seleccionan archivos .ts y se les aplica stripTypeScriptTypes. Después se crea createApplication con una base en memoria y se cierra. No abre un puerto ni cambia la base de tu servidor.')
p('El mensaje informa cuántos archivos se han recorrido. Añadir un archivo TypeScript al directorio puede aumentar ese número sin añadir una prueba de negocio nueva. Una importación incorrecta en un módulo realmente cargado también puede fallar al construir; un tipo incompatible no queda descartado por esta comprobación.')
h('Ejecuta antes de una suite más lenta')
code('node scripts/check.ts', 'bash')
p('Cuando te equivoques en una comilla, una llave o una anotación incompatible con el modo de eliminación de tipos, arregla ese error antes de interpretar las pruebas posteriores. Para análisis estático se necesita preparar tsc y los tipos apropiados, tal como se explica en ampliaciones.')

chapter('scripts/reset.ts: reiniciar datos con una copia', 'Una herramienta de demostración debe hacer explícito cuándo sustituye datos.')
fileintro('scripts/reset.ts','Restablecer datos ficticios tras crear una copia de la base existente.','La aplicación está detenida y solo manejas datos de demostración.','Puedes repetir los escenarios sin borrar a ciegas el archivo SQLite.')
h('El recorrido del script')
steps('Calcula la ruta por defecto o CICT_DB.', 'Si falta --confirmar, muestra instrucciones y termina sin reiniciar.', 'Crea el directorio y abre la conexión.', 'Si ya existía el archivo, usa backup de node:sqlite para guardarlo en data/backups con fecha.', 'Elimina filas en orden compatible con claves externas, dentro de una transacción.', 'Llama a seedDatabase para generar otra vez cuentas, equipo y fechas.', 'Cierra la conexión en finally.')
p('La copia usa la función de SQLite y no una copia improvisada del archivo mientras hay un WAL activo. Detén el servidor antes de usarla para que tu navegador no mantenga una sesión del estado anterior. La transacción de borrado se confirma antes de la semilla; si la reinserción fallara, conserva la copia para recuperar el estado. No afirmes que ambos pasos están contenidos en la misma transacción.')
h('Cómo probarlo de forma segura')
code('node scripts/reset.ts\n# Solo si quieres reiniciar tus datos ficticios y has detenido el servidor:\nnode scripts/reset.ts --confirmar', 'bash')
p('La primera orden solo informa. La segunda muestra la copia si correspondía y confirma el reinicio. No uses esta herramienta como una migración de producción ni sobre un archivo ajeno solo porque puedas pasar su ruta mediante una variable de entorno.')

chapter('scripts/browser-check.ts: probar los clics de verdad', 'Revisión opcional del navegador y capturas, sin instalar otra biblioteca de automatización.')
fileintro('scripts/browser-check.ts','Conducir Firefox por WebDriver BiDi y comprobar recorridos y móvil.','Firefox temporal con depuración remota y loopback permitidos.','Las pantallas y formularios se verifican además de las reglas y HTTP.')
h('Qué necesitas y qué no cambia')
p('La aplicación normal no necesita Firefox ni este script para arrancar. La revisión crea un servidor adicional de prueba y una base en memoria. No utiliza ni borra data/prototipo.sqlite. El perfil de navegador se crea en /tmp para separarlo de tu Firefox personal.')
code('mkdir -p /tmp/sg-cict-firefox\nfirefox --headless --no-remote --profile /tmp/sg-cict-firefox --remote-debugging-port 9223', 'bash', 'Primera terminal: navegador temporal')
code('node --test --test-isolation=none scripts/browser-check.ts', 'bash', 'Segunda terminal: conducir el recorrido')
h('Escribe el control de mensajes')
p('Un WebSocket conecta con /session. sequence asigna ids a comandos y pending relaciona cada id con su promesa, temporizador y respuesta. Un mensaje de error rechaza la promesa; un resultado la resuelve. Los eventos log.entryAdded se guardan para comprobar que no haya errores de JavaScript en el navegador.')
p('send exige conexión abierta y un límite de espera. session.new abre la sesión y session.end debe cerrarla antes de cerrar el socket. Si queda una sesión remota anterior activa puede aparecer Maximum number of active sessions: detén el Firefox temporal y vuelve a lanzarlo, sin tocar tu perfil habitual.')
h('Las ayudas del recorrido')
table(['Ayuda','Qué facilita'],[['evaluate','Ejecuta una expresión en el contexto de la pestaña y serializa su resultado como JSON.'],['wait','Reintenta una condición un tiempo limitado, sin un sleep fijo enorme.'],['click','Busca un selector y pulsa su elemento.'],['fill','Establece el valor de un campo y emite input. Para mes se emite change expresamente.'],['go','Cambia el hash y espera la navegación activa.'],['capture','Pide una captura PNG y la guarda dentro de docs/capturas.']])
h('Por qué se espera a la interfaz')
p('Cambiar la resolución puede iniciar la transición del menú móvil. El script espera a que la barra lateral quede fuera antes de capturar. También espera a que el aviso deje de verse. Una captura durante una transición no es evidencia de que la pantalla final esté mal; las condiciones observadas hacen repetible esa verificación.')
h('Recorridos que comprueba')
bullets('Acceso administrativo y cuatro indicadores del panel.', 'Búsqueda de balanza, disponibilidad, reserva y cancelación.', 'Parte sobre un equipo, reparación y alta externa.', 'Informe con un mes que contiene sesiones finalizadas, incluso al empezar un mes nuevo.', 'Documentación accesible por su ruta.', 'Pantalla de 390 px sin desbordamiento horizontal global y botón de menú.', 'Perfil UCO sin opciones administrativas y rechazo de un contrato vencido.')
p('El script también guarda cinco capturas. Los datos que se ven son los de su base de prueba, con acciones realizadas durante el recorrido. Para ampliar la revisión, añade una aserción sobre un efecto real y espera su resultado; no te limites a tomar más imágenes.')

chapter('README, docs y archivos de apoyo: documentar lo que existe', 'La documentación también se construye archivo por archivo.')
h('README.md: la puerta de entrada')
p('Crea README.md en la raíz de tu aplicación. Debe permitir a alguien arrancar sin leer el chat: objetivo, versión de Node, comando, URL, credenciales ficticias, funcionalidades, comprobaciones, configuración y límites. Añade enlaces relativos que funcionen en el repositorio. No copies credenciales reales de un entorno institucional.')
steps('Escribe una descripción de dos o tres frases de lo que hace la aplicación.', 'Incluye la carpeta desde la que ejecutar node src/server.ts.', 'Explica que Node debe permanecer abierto y que Ctrl+C lo detiene.', 'Añade los perfiles de demostración y la contraseña pública de ejemplo.', 'Enlaza los documentos de estudio y las capturas.', 'Indica qué está simulado y cómo se guardan o reinician los datos.', 'Comprueba cada enlace local desde el propio archivo.')
code('# Mi SG-CICT\n\nAplicación local de reservas e incidencias para estudiar su implementación.\n\n## Ejecutar\n\nDesde esta carpeta: node src/server.ts\nAbre http://localhost:4173 y conserva la terminal abierta.\n\n## Referencia\n\nConsulta [la arquitectura](docs/ARQUITECTURA.md).', 'markdown', 'Plantilla mínima de README que luego debes completar')
h('docs/ARQUITECTURA.md')
p('Explica módulos, responsabilidades, flujo y persistencia. Reproduce el recorrido de una reserva desde el formulario a la transacción. Incluye un mapa de carpetas y la distinción entre estado persistente del equipo y mantenimiento temporal. Describe DatabaseSync como una decisión de escala local, sin atribuirle una capacidad medida que no has probado.')
h('docs/GUIA-CODIGO.md')
p('Escribe una ruta de lectura para una primera sesión y una tabla «quiero cambiar X, empiezo en Y». Añade un ejemplo de cómo ampliar una regla con su prueba. Este archivo orienta sobre el código; el manual de usuario explica cómo utilizar las pantallas. Mantén esa diferencia para que ninguno quede lleno de información que no necesita su lector.')
h('docs/DECISIONES.md')
p('Registra cada punto ambiguo junto a la decisión del prototipo y su efecto. Ejemplos: exactamente siete días, rechazo del mantenimiento incompatible, contratos incluidos hasta final del día y turnos técnicos simplificados. Distingue esas decisiones de requisitos confirmados; no presentes una interpretación como un acuerdo con el cliente que no se ha producido.')
h('docs/API.md')
p('Enumera método, ruta, acceso, cuerpo y respuesta de cada operación. Incluye estados de error y ejemplos de JSON que identifiques como ilustrativos. Explica cookie y CSRF sin publicar tokens de sesiones reales. La lista de rutas debe coincidir con server.ts; una función del dominio no es automáticamente un endpoint.')
h('docs/MANUAL-USUARIO.md')
p('Para cada perfil, describe el recorrido con nombre de pantalla, botón, campos, resultado y qué hacer si se rechaza. Incluye acceso, reserva, cancelación, avería, reparación, uso real, informe y cuentas. Explica cuándo la semilla incluye una sesión en curso y por qué algunos ejemplos finalizados pueden pertenecer al mes anterior.')
h('docs/REQUISITOS.md')
p('Relaciona RF-01 a RF-30 con comportamiento observable y su ubicación en el código. Identifica Moodle y correo como simulados. No marques un requisito no funcional como verificado solo porque la página haya cargado una vez. Conserva la referencia a la P2 y las decisiones abiertas que afectan al comportamiento.')
h('docs/PRUEBAS.md')
p('Anota entorno, comandos realmente utilizados, casos, resultado y limitaciones. Explica el conteo de las subpruebas para no inflar resultados. Registra problemas encontrados y su corrección, como el desbordamiento móvil y la preparación del uso real en un reloj avanzado. No escribas «superado» para pruebas que solo has pensado ejecutar.')
h('docs/PLAN-TRABAJO.md')
p('Propón reparto por recorridos y producto de cada sprint, pero separa propuesta de evidencia de trabajo pasado. Una tabla de planificación no demuestra que un integrante haya escrito cierto código ni sustituye los registros reales de GitHub o del tablero. Añade un guion de demostración para el vídeo sin fingir que el vídeo ya existe.')
h('Las capturas y data/.gitkeep')
p('Los cinco PNG se pueden generar con browser-check.ts. Una captura es un archivo binario: no tienes que escribir su contenido como texto. Para compararte, usa la imagen que corresponda a tu etapa. data/.gitkeep debe estar vacío; su única finalidad es conservar el directorio en Git cuando la base todavía no existe.')
h('Lista de apoyo completa')
table(['Ruta','Cómo obtenerla'],[['docs/capturas/01-acceso.png','Captura del acceso sin sesión.'],['docs/capturas/02-panel.png','Captura del panel autenticado.'],['docs/capturas/03-catalogo.png','Captura de catálogo sin filtro.'],['docs/capturas/04-informes.png','Captura de un periodo con consumo.'],['docs/capturas/05-movil.png','Captura a 390 × 844 sin menú desplegado.'],['data/.gitkeep','Crea un archivo vacío con ese nombre exacto.'],['data/prototipo.sqlite y auxiliares','Los genera SQLite al ejecutar la aplicación; no se escriben a mano.']])
note('Las rutas de los PDFs originales son externas al ejemplo aislado', 'El README del prototipo del repositorio enlaza a ../docs/entregas y ../docs/enunciados. Si trabajas en una carpeta independiente sin esa estructura, ajusta esos enlaces o conserva las fuentes originales en una ubicación que documentes. No es un fallo del servidor.')

chapter('Construcción guiada en diez hitos', 'Un recorrido práctico para no convertir el anexo en un ejercicio de copiar a ciegas.')
h('Hito 1 · Directorios y configuración')
steps('Crea la carpeta de aprendizaje y los seis directorios de trabajo.', 'Escribe package.json, .gitignore y data/.gitkeep.', 'Comprueba versión de Node y disponibilidad de DatabaseSync.', 'Anota en un README inicial la orden y la carpeta desde la que vas a ejecutar.')
p('Resultado comprobable: puedes explicar por qué la raíz del proyecto no es src y por qué la base no debe subirse a Git. Todavía no hay servidor que arrancar.')
h('Hito 2 · Modelo y tiempo')
steps('Escribe model.ts y time.ts completos.', 'Ejecuta una importación de parseLocalDateTime con un día de verano y otro de invierno.', 'Calcula dos intervalos adyacentes y otros solapados.', 'Explica la diferencia entre una fecha local de formulario y un instante almacenado.')
p('Resultado: el cálculo de reglas temporales no depende de una pantalla. Si una importación falla, revisa nombres y extensiones antes de seguir.')
h('Hito 3 · Esquema y conexión')
steps('Escribe schema.sql con sus siete tablas y sus índices.', 'Escribe openDatabase y transaction.', 'Abre una base en memoria y consulta sqlite_master.', 'Cierra la conexión. Comprueba que no has creado datos persistentes por accidente.')
p('Resultado: SQLite reconoce el esquema. No necesitas instalar ni arrancar un servidor de base de datos distinto.')
h('Hito 4 · Acceso y semilla')
steps('Escribe auth.ts y seed.ts.', 'Crea una base en memoria y llama a seedDatabase.', 'Accede con UCO y comprueba que el rol sea uco.', 'Prueba una contraseña incorrecta y la cuenta caducada.', 'Cierra una sesión e intenta recuperarla de nuevo.')
p('Resultado: tienes identidades y acceso probables desde TypeScript. No hay razón para inventar un usuario dentro de una futura ruta HTTP.')
h('Hito 5 · Reglas de reservas')
steps('Escribe las ayudas, constructor, permisos y plan de CictSystem.', 'Añade availability y createBooking.', 'Prueba balanza libre, balanza repetida y dos equipos que necesitan técnico.', 'Implementa cancelBooking y comprueba ambos lados del límite de 24 horas.', 'Añade las pruebas de prioridad con reloj controlado.')
p('Resultado: puedes describir por qué se acepta o rechaza cada cita. Si te cuesta saber dónde comprobar una condición, mantén la comprobación en plan o en la operación correspondiente, sin duplicarla en cada ruta.')
h('Hito 6 · Incidencias, uso, cuentas e informes')
steps('Completa los métodos restantes de CictSystem.', 'Prueba que averiar conserva la cita y bloquea nuevas.', 'Abre dos partes y resuelve solo uno: debe continuar averiado.', 'Registra un uso real completo y un informe.', 'Solicita snapshot como investigador y revisa qué datos ajenos faltan.')
p('Resultado: el módulo de reglas completo puede funcionar sin HTML. Aquí es útil ejecutar tests/system.test.ts para verificar que no solo funciona tu caso feliz.')
h('Hito 7 · HTTP y documento inicial')
steps('Escribe server.ts y el index.html completo.', 'Crea ui.ts, views.ts y app.ts provisionales con export {} si todavía no los has escrito.', 'Crea styles.css y favicon.svg, aunque la primera hoja pueda estar vacía.', 'Arranca una sola instancia y comprueba /health.', 'Verifica GET state sin sesión: debe ser 401, no datos del administrador.')
p('Resultado: existe un servidor real y un documento que puede cargar módulos. Es normal que la página todavía esté en su estado inicial mientras app.ts siga vacío.')
h('Hito 8 · Pantallas y eventos')
steps('Sustituye ui.ts por su versión completa.', 'Escribe views.ts pantalla por pantalla.', 'Completa app.ts: primero acceso y estado, después reserva y refresco, luego el resto.', 'Reinicia Node tras cada cambio de los .ts del navegador.', 'Comprueba un recorrido de creación y recarga antes de abordar todos los detalles visuales.')
p('Resultado: los datos que aparecen en pantalla proceden del servidor. Si solo añades objetos locales al array, aún no has conectado el recorrido completo.')
h('Hito 9 · Estilo y móvil')
steps('Completa CSS por sus ocho grupos.', 'Compara acceso, panel y catálogo con las capturas.', 'Prueba a 390 px, teclado y diálogos.', 'Comprueba que una tabla puede desplazarse sin ensanchar toda la página.', 'Haz una captura propia e identifica una diferencia concreta antes de ajustar valores.')
p('Resultado: una interfaz legible y utilizable. No hace falta que cada píxel sea idéntico para que entiendas la construcción, pero no ocultes errores funcionales con estilos.')
h('Hito 10 · Pruebas, reinicio y documentación')
steps('Completa las tres suites y ejecuta la orden global.', 'Añade scripts/check.ts y reset.ts; prueba reinicio solo sobre datos ficticios y con copia.', 'Ejecuta browser-check si dispones de Firefox y puertos locales.', 'Termina README y los ocho documentos.', 'Escribe qué podrías explicar sin consultar la solución y qué necesitas practicar de nuevo.')
code('node scripts/check.ts\nnode --test --test-isolation=none tests/*.test.ts\nnode src/server.ts', 'bash', 'Secuencia de verificación y arranque final')
note('No arranques dos copias para seguir la secuencia', 'Si ya tienes node src/server.ts abierto, deja esa terminal y utiliza otra para las pruebas. La última orden solo hace falta cuando el servidor no está escuchando. Las pruebas HTTP usan otro puerto temporal.')

chapter('Tres operaciones seguidas de extremo a extremo', 'Aprende a localizar un fallo pasando por las piezas que intervienen realmente.')
h('Recorrido 1 · Crear una reserva de balanza')
diagram('Del formulario al estado confirmado', ['bookingDialog\napp.ts','POST bookings\nserver.ts','createBooking\nsystem.ts','GET state\nrenderShell'])
steps('views.catalog muestra una tarjeta con data-action book y el identificador de la balanza.', 'El manejador de clics abre bookingDialog.', 'El formulario guarda campos date, start, end, instrumentId y purpose.', 'submit convierte esos campos con bookingInput.', 'request envía JSON con cookie y CSRF.', 'server obtiene actor de la sesión y llama createBooking.', 'plan comprueba que la balanza está disponible y no necesita técnico.', 'La transacción inserta reserva, aviso y actividad.', 'El navegador cierra el diálogo, pide snapshot y muestra el nuevo estado.')
p('Si la reserva se ve y desaparece al recargar, comprueba si realmente hubo POST y fila en la base. Si el servidor devuelve 409 pero la interfaz muestra éxito, revisa el manejo de response.ok. Si el POST es correcto pero no se ve la fila, revisa filtros, propiedad y el GET state posterior.')
h('Recorrido 2 · Incidencia, bloqueo y reparación')
steps('Un investigador abre un parte de la balanza con descripción suficiente.', 'createIncident inserta el parte y actualiza instruments.state a averiado.', 'Se generan avisos a usuarios con citas afectadas, sin borrar esas citas.', 'Un intento posterior de experimento falla en plan antes de insertar.', 'Un técnico abre resolución y envía el trabajo realizado.', 'resolveIncident verifica si hay otro parte abierto.', 'Solo la última resolución libera el equipo y produce sus avisos correspondientes.')
p('Si resuelves un parte y sigue averiado, busca otros partes abiertos antes de atribuirlo a la interfaz. Si aparece disponible pero se rechaza la franja, podría estar ocupada o no haber técnico: estado del equipo y disponibilidad temporal no son lo mismo.')
h('Recorrido 3 · Uso real e informe')
steps('Durante la franja prevista, el técnico asignado registra start.', 'El servidor guarda su hora actual en actualStart.', 'Más tarde registra finish y se guarda actualEnd.', 'Contabilidad solicita un mes.', 'report selecciona usos finalizados y recorta la duración al intervalo mensual.', 'Agrupa por persona y equipo; añade aparte cancelaciones tardías.', 'La vista y el CSV usan las mismas filas calculadas por el servidor.')
p('Si el informe no tiene una sesión en curso, ese resultado es correcto: aún no hay fin real. Si es el primer día del mes, los ejemplos del día anterior pertenecen al mes anterior. Si las horas no coinciden con la duración programada, recuerda que el informe usa actualStart/actualEnd.')
h('Una regla para investigar fallos')
p('Empieza por la primera observación que difiere de lo esperado: clic, petición, respuesta, cambio de base o representación. Cambia una cosa y vuelve a ejecutar el mismo recorrido. No reescribas todo el formulario ni reinicies los datos sin saber qué condición se incumplía.')

chapter('Errores frecuentes y cómo resolverlos', 'Referencia de terminal, navegador, datos y reglas para consultar mientras construyes.')
table(['Síntoma','Qué significa y qué comprobar'],[
 ['Cannot find module .../src/server.ts','Carpeta actual o nombre incorrectos. Revisa pwd y ls, entra en la raíz de la app y utiliza la ruta correspondiente.'],
 ['EADDRINUSE 127.0.0.1:4173','Ya existe un proceso escuchando ahí. Usa la instancia abierta, detén la tuya anterior o cambia PORT.'],
 ['ExperimentalWarning: stripTypeScriptTypes','Aviso del módulo de Node utilizado en la transformación. No es por sí solo un fallo de arranque.'],
 ['No such built-in module: node:sqlite','La instalación de Node no ofrece el módulo necesario. Verifica versión y distribución.'],
 ['listen EPERM','El entorno impide escuchar en ese puerto o interfaz. Distingue restricción del entorno de puerto ocupado.'],
 ['La página se abre como file:// y no accede','Debes visitar la URL HTTP del servidor. Las rutas /assets y /api necesitan ese origen.'],
 ['Página en Preparando tu espacio','Revisa red, consola, app.js y existencia de ui.js/views.js. Un andamio export {} todavía no inicia la interfaz.'],
 ['Cambié views.ts y no cambia la página','El JavaScript se prepara al construir el servidor. Reinicia Node y después recarga.'],
 ['Cambié CSS pero parece igual','Recarga, revisa la regla y su prioridad. Si el navegador conserva caché, prueba recarga completa.'],
 ['401 al pedir state sin haber entrado','Comportamiento previsto. Inicia sesión antes de consultar estado autenticado.'],
 ['403 formulario caducado','CSRF no coincide o sesión inválida. Recarga, inicia sesión y vuelve a abrir el formulario.'],
 ['403 contrato no vigente','El acceso o el fin solicitado no están cubiertos. Administración puede revisar la vigencia según el caso.'],
 ['409 franja protegida','Hay conflicto que las reglas no permiten desplazar. No se resuelve ocultando el mensaje; elige otra franja.'],
 ['No hay técnico disponible','La ocupación técnica incluye otros instrumentos y mantenimiento. Revisa ambas agendas.'],
 ['No puede iniciar uso aunque llegó la hora','Comprueba técnico asignado, franja, equipo averiado y sesiones reales aún abiertas.'],
 ['Reparé un parte y sigue bloqueado','Puede quedar otro parte del mismo equipo abierto.'],
 ['La semilla no añade mi nuevo equipo','Solo se aplica a una base sin cuentas. Usa otra base de demostración o reinicia con copia.'],
 ['database is locked','Otra transacción está ocupando la escritura. Revisa procesos y que las transacciones se cierren. No borres el archivo para resolverlo.'],
 ['Error de columna tras editar schema.sql','CREATE IF NOT EXISTS no migra tablas existentes. Necesitas nueva base de ejemplo o una migración.'],
 ['Comas entre tarjetas','Probablemente interpolaste el resultado de map sin join vacío.'],
 ['Un <b> aparece como etiqueta inesperada','Revisa si has omitido escape antes de interpolar datos en HTML.'],
 ['La tabla ensancha todo el móvil','Revisa el contenedor desplazable, mínimos de Grid y posiciones de elementos ocultos accesibles.'],
 ['Informe vacío o mes inesperado','Comprueba sesiones finalizadas y fechas reales dentro del periodo; la semilla puede quedar en el mes anterior.'],
 ['Maximum number of active sessions en Firefox','Quedó una sesión remota temporal activa. Detén y reinicia ese Firefox de prueba, no tu navegador personal.']])
h('Qué información guardar cuando no encuentres el fallo')
bullets('Comando exacto y carpeta de ejecución.', 'Versión de Node y si el servidor ya estaba abierto.', 'Acción, perfil y valores relevantes del formulario; nunca contraseñas reales.', 'Estado HTTP y mensaje legible de respuesta.', 'Esperado y observado, incluyendo fecha del reloj cuando se trate de límites.', 'Una prueba o recorrido breve que vuelva a producirlo.')

chapter('Ejercicios para apropiarte del proyecto', 'Cambios pequeños con una solución orientativa, separados de la copia original.')
h('Ejercicio 1 · Encontrar un instrumento por sala')
p('Objetivo: que buscar «Sala 03» encuentre sus equipos. Es un cambio de filtro de presentación. No debes abrir nuevas rutas HTTP ni tocar la reserva de salas.')
steps('Localiza en views.catalog la cadena utilizada para includes.', 'Añade room al conjunto de campos buscables.', 'Reinicia el servidor por el cambio en TypeScript público.', 'Busca Sala 03 y comprueba la balanza y la centrífuga.')
code("(i.name + ' ' + i.code + ' ' + i.category + ' ' + i.room)\n  .toLowerCase()\n  .includes(f.search.toLowerCase())", 'typescript', 'Pista de solución: expresión que sustituirías en el filtro')
h('Ejercicio 2 · Añadir un equipo autónomo a la semilla')
p('Objetivo: añadir una estufa con código EST-007. Escribe una nueva fila de instruments con técnica, sala, descripción, needsTechnician=0, una paleta existente y un icono conocido. Crea otra base de demostración para observarlo. Cambiar solo la semilla no modifica la base actual.')
code('CICT_DB=/tmp/sg-cict-estufa.sqlite PORT=4301 node src/server.ts', 'bash', 'Probar otro conjunto de datos sin cambiar la base anterior')
p('Comprueba que aparece en el catálogo, que se puede reservar y que technicianId queda null. Pregúntate por qué el nuevo aparato no reserva toda su sala.')
h('Ejercicio 3 · Mostrar cuántas incidencias abiertas tiene cada equipo')
p('Objetivo: enriquecer una tarjeta sin duplicar el estado de avería. Cuenta en s.incidents los partes del mismo instrumentId con resolvedAt null y muestra el total con texto escapado. No añadas una columna contador si puedes calcularlo del estado ya disponible.')
code('const abiertas = s.incidents.filter(\n  parte => parte.instrumentId === i.id && parte.resolvedAt === null\n).length;', 'typescript', 'Cálculo local dentro de instrumentCard')
p('Prueba cero, una y dos incidencias. Asegúrate de que cerrar solo una de dos cambia el contador pero no habilita la reserva.')
h('Ejercicio 4 · Hacer estrictamente futuro el inicio')
p('Objetivo: cambiar una decisión concreta del límite temporal, no el formato de fecha. Si decides que inicio igual a now debe rechazarse, cambia start < now a start <= now en validateSlot. Prepara primero un reloj fijo con igualdad exacta y escribe el esperado nuevo. Actualiza después la documentación de la regla.')
p('El resto de casos debe seguir pasando. No resuelvas el límite redondeando now al día o ignorando segundos: estarías cambiando más de una regla.')
h('Ejercicio 5 · Añadir una duración máxima acordada')
p('Supón que el cliente acuerda un máximo de cuatro horas por reserva de experimento. El prototipo original no impone ese máximo. Implementarlo requiere decidir si el mantenimiento se limita también. Coloca la regla según esa decisión: en plan para distinguir tipo, o en validateSlot si de verdad afecta a todas las franjas.')
steps('Escribe el criterio: exactamente cuatro horas permitido, cuatro horas y un minuto rechazado.', 'Añade los dos casos de prueba.', 'Implementa la comparación usando HOUR y el intervalo numérico.', 'Añade un mensaje comprensible.', 'Actualiza manual y matriz para que no contradigan el comportamiento.')
h('Ejercicio 6 · Cubrir una carrera de disponibilidad')
p('Comprueba disponibilidad de una franja libre, crea otra reserva para esa franja y después intenta confirmar la primera. El esperado es conflicto al confirmar. No necesitas iniciar dos hilos para demostrar que una respuesta de disponibilidad anterior no es una autorización permanente.')
p('La solución utiliza la misma operación pública que la aplicación: availability, createBooking y otro createBooking con una cuenta distinta cuando proceda. El test debe observar el resultado final, no buscar el nombre plan dentro del código.')
h('Ejercicio 7 · Una ruta nueva de consulta limitada')
p('Propón consultar solo instrumentos operativos sin devolver datos de cuentas. Define primero el resultado, los perfiles que lo necesitan y una prueba HTTP de sesión ausente. Después decide si de verdad hace falta una ruta nueva o si el snapshot ya ofrece la información de forma suficiente. El objetivo del ejercicio es justificar una interfaz pequeña, no añadir archivos por costumbre.')

chapter('Ampliaciones y decisiones pendientes', 'Qué cambiarías si el proyecto saliera de la demostración local.')
h('Análisis estático de TypeScript')
p('Para añadir comprobación de tipos necesitas instalar TypeScript y los tipos del entorno de Node en tu entorno de desarrollo. Configura noEmit y la resolución de módulos coherente con tus importaciones. El navegador necesita bibliotecas DOM; el servidor utiliza módulos de Node. Separa o referencia configuraciones si mezclar ambos entornos produce supuestos incorrectos sobre globals.')
p('No incluyas por inercia una salida JavaScript duplicada y un segundo servidor si tu objetivo actual es solo comprobar tipos. Mantén claro qué comando analiza y cuál ejecuta. La copia original de este manual no incorpora una configuración tsc ni declara un resultado estático superado.')
h('Moodle e identidad institucional')
p('Un adaptador de identidad real necesita el mecanismo autorizado por la universidad, sus permisos y un entorno de pruebas. No se sustituye con una llamada improvisada que envíe credenciales a una URL. Conserva las operaciones de negocio independientes de cómo se obtuvo la identidad y documenta qué atributos y garantías necesita la sesión.')
h('Correo real y transacciones')
p('notify actualmente escribe una fila en la misma transacción. Enviar un correo externo no se puede deshacer con ROLLBACK. Una ampliación razonable registra un mensaje pendiente dentro de la transacción y utiliza después un proceso de envío con reintentos e identificación de duplicados. Distingue confirmado en SQLite de entregado por correo.')
h('Contratos, clientes y técnicos')
p('La cuenta contiene una entidad y un intervalo contractual. Varios contratos por cliente, equipos con especialidades y calendarios laborales justifican un modelo más rico. Empieza por ejemplos de reglas reales y por las consultas necesarias, no por crear una tabla o una clase para cada sustantivo sin uso.')
h('Migraciones y operación')
p('Los cambios de esquema persistente necesitan versión y pasos reproducibles. Conserva copias verificables, comprueba restauración y define qué ocurre si falla una migración. Un reinicio de semilla para datos ficticios no es una política de conservación de datos reales.')
h('Escala y seguridad del despliegue')
p('Revisa bloqueo del proceso por operaciones síncronas, límites de entrada, sesiones, HTTPS, secretos, permisos del archivo, registros y copias. Añade pruebas de concurrencia entre conexiones y mediciones del catálogo bajo el entorno previsto. Estas tareas deben responder a un alcance concreto; el manual no afirma que la demostración ya las resuelva.')
h('Entrega académica')
p('La P4 original propone C++/Eclipse/CUTE, mientras que esta construcción utiliza TypeScript, HTML y CSS por tu elección posterior. El ejemplo sirve para aprender y explorar. La aceptación del stack, las plantillas, autoría de pruebas, idioma documental, vídeo y evidencias de trabajo semanal corresponden a vuestra entrega y deben comprobarse con el profesor.')

chapter('Glosario y hoja de consulta', 'Definiciones breves para volver al código sin detenerte en cada término.')
table(['Término','Significado en esta aplicación'],[
 ['Actor','Persona autenticada que solicita una operación; se obtiene de la sesión.'],['Anotación de tipo','Descripción que orienta al analizador y se elimina antes de ejecutar en este arranque.'],['API HTTP','Conjunto de rutas y formatos que el navegador utiliza para pedir operaciones.'],['Asíncrono','Trabajo cuyo resultado se obtiene después mediante una promesa.'],['Autenticación','Comprobar a qué cuenta corresponden unas credenciales o una sesión.'],['Autorización','Comprobar si esa cuenta puede ejecutar una operación.'],['Base en memoria','SQLite que vive solo mientras está abierta esa conexión.'],['Callback','Función que se pasa para que otra parte del programa la ejecute.'],['Clave externa','Referencia de una fila a otra que debe existir.'],['Cookie','Dato de sesión que el navegador envía al servidor según sus reglas de origen y ruta.'],['CSRF','Protección frente a escrituras originadas fuera del recorrido esperado de la sesión.'],['CSP','Política del navegador sobre recursos y formas de ejecutar contenido.'],['DOM','Árbol de elementos que representa el HTML y puede manipular JavaScript.'],['Endpoint','Ruta y método que aceptan una consulta u operación HTTP.'],['Escape HTML','Conversión de caracteres para mostrar texto sin interpretarlo como etiquetas.'],['Fixture','Preparación repetible de una prueba: datos, base, reloj y ayudas.'],['Hash o resumen','Valor derivado; no es un cifrado que se descifre para recuperar el original.'],['HttpOnly','Atributo de cookie que impide leerla con el JavaScript habitual del documento.'],['Idempotencia','Propiedad de repetir una operación sin multiplicar su efecto lógico.'],['Índice SQL','Estructura que ayuda a localizar filas; no sustituye una regla de negocio.'],['Interface TypeScript','Descripción de forma de un dato, sin validación automática en ejecución.'],['Intervalo semiabierto','Incluye inicio y excluye fin; permite citas consecutivas.'],['JSON','Representación textual de objetos, listas y valores intercambiados.'],['Loopback','Interfaz local del equipo, como 127.0.0.1.'],['Módulo','Código con una interfaz de uso y una implementación.'],['Persistencia','Capacidad de conservar datos después de cerrar una conexión o un proceso.'],['Promesa','Representación del resultado futuro de una operación.'],['Consulta preparada','SQL con valores vinculados por parámetros en lugar de concatenar entradas.'],['Renderizar','Construir o actualizar la representación visible de un estado.'],['Rol','Perfil de permisos, diferente de la identidad de una persona.'],['Sal','Valor aleatorio utilizado junto a una contraseña al derivar su resumen.'],['Semilla','Datos ficticios iniciales para una base vacía.'],['Snapshot','Estado de consulta adaptado a la persona autenticada.'],['Transacción','Conjunto de cambios que se confirma completo o se revierte.'],['UTC','Referencia temporal que permite representar un instante independiente de una zona local.'],['WAL','Modo de registro de SQLite que puede crear archivos auxiliares.']])
h('Comandos de uso diario')
code('node --version\nnode scripts/check.ts\nnode --test --test-isolation=none tests/*.test.ts\nnode src/server.ts\n# Otra instancia, con puerto distinto:\nPORT=4300 node src/server.ts\n# Solo con datos ficticios y el servidor detenido:\nnode scripts/reset.ts --confirmar', 'bash')
h('Credenciales de la copia de referencia')
table(['Perfil','Correo'],[['Administración','admin@demo.local'],['Investigación UCO','uco@demo.local'],['Investigación externa','externa@demo.local'],['Personal técnico','tecnico@demo.local'],['Segundo técnico','tecnico2@demo.local'],['Contabilidad','contable@demo.local'],['Consulta','consulta@demo.local'],['Contrato caducado','caducado@demo.local']])
p('Todas las cuentas de la semilla utilizan Demo2026!. El alta de una cuenta nueva exige una contraseña de al menos diez caracteres. El servidor se visita en http://localhost:4173 cuando no se ha cambiado PORT.')

chapter('Fuentes y cómo comprobar esta edición', 'El manual tiene una copia verificable del código que explica.')
h('Fuentes primarias y documentación')
bullets('Código de la carpeta prototipo: fuente directa de todos los listados del anexo.', 'P2 del equipo: docs/entregas/P2_equipo204.pdf en el repositorio original.', 'P4: docs/enunciados/p4-enunciado.pdf y p4-diapositivas.pdf.', 'Node TypeScript: https://nodejs.org/api/typescript.html', 'Node SQLite: https://nodejs.org/api/sqlite.html', 'Node HTTP y pruebas: https://nodejs.org/api/http.html y https://nodejs.org/api/test.html', 'Node criptografía: https://nodejs.org/api/crypto.html', 'HTML y DOM: https://developer.mozilla.org/en-US/docs/Web/HTML y https://developer.mozilla.org/en-US/docs/Web/API', 'SQLite y transacciones: https://www.sqlite.org/lang_transaction.html')
p('La aplicación se verificó en la construcción original con Node 26.13.1. Para preparar este libro se han revisado el contenido real, las rutas y los límites del ejemplo. Los resultados anteriores de pruebas aparecen en la documentación de referencia; la creación del PDF no necesita detener tu servidor ni modificar su base.')
h('Integridad y material complementario')
p('manifest.json enumera archivos y SHA-256, páginas del índice y comprobaciones de maquetación. El ZIP incluye los archivos fuente y las cinco capturas; excluye SQLite, sesiones, copias, .git y el propio directorio del manual. No introduce paquetes nuevos en la aplicación.')
p('generar_manual.py y contenido_manual.py son los archivos editoriales que permiten regenerar PDF y HTML. Utilizan Python, Cairo, Pango y Pygments en el entorno de edición; esas herramientas no son dependencias de la aplicación Node. Este libro explica la aplicación, no exige que escribas un generador de PDFs para poder reservar un equipo.')
h('Antes de dar por terminado tu aprendizaje')
steps('Arranca tu copia desde su carpeta sin consultar el chat.', 'Explica qué archivo recibe un POST y cuál decide la prioridad.', 'Demuestra una reserva, una cancelación, una incidencia y una reparación.', 'Muestra una prueba de límite temporal y otra de permiso denegado.', 'Recarga y reabre la aplicación para comprobar persistencia.', 'Señala al menos tres límites reales de la demostración.', 'Escribe una pequeña mejora, su comprobación y la documentación que cambia.')
note('Cómo usar el anexo A', 'Cada archivo empieza en una página identificada por su ruta y tiene una entrada propia en el índice del PDF. El código está completo. Escribe por bloques apoyándote en el capítulo explicativo y utiliza la copia íntegra para comprobar detalles, no como sustituto de entender qué efecto debe producir cada función.')
